// ---------- 狀態與觸控鏡頭 ----------
var state={mode:'ground',rot:285,height:1.8,exp:1,sun:true,obj:false,hero:true,follow:true};
var pano={theta:Math.atan2(-0.753,-0.549)+0.5,phi:Math.PI/2};
// ---------- 操作：左半邊搖桿移動、右半邊拖曳轉鏡頭、雙指縮放；鍵盤 WASD（Shift 慢爬） ----------
// 鏡頭：兔子視角的第三人稱（低角度、貼近兔子眼睛高度），移動時自動轉到兔子背後
var cam={theta:Math.PI,phi:1.3,r:4.6,target:[0,1.3,0],hold:0};
var pin={x:0,z:0,mag:0},input={x:0,z:0,mag:0},joy=null,look2=null,pinch=0,keys={},joyEl=$('joy'),knobEl=joyEl.querySelector('i');
var ptrs=new Map();
canvas.addEventListener('pointerdown',function(e){try{canvas.setPointerCapture(e.pointerId);}catch(_){}
  ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(ptrs.size===2){joy=null;look2=null;joyEl.style.display='none';var a=Array.from(ptrs.values());pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);return;}
  if(e.clientX<innerWidth*0.5&&!joy){joy={id:e.pointerId,x0:e.clientX,y0:e.clientY,x:e.clientX,y:e.clientY};joyEl.style.left=e.clientX+'px';joyEl.style.top=e.clientY+'px';joyEl.style.display='block';knobEl.style.transform='';hideHint();}
  else if(!look2)look2={id:e.pointerId,x:e.clientX,y:e.clientY};});
