  function box(col,r,met,cx,cy,cz,w,h,d,ry){put(mb,col,r,met,[cx,cy,cz],ry,[w,h,d]);}
  function cyl(col,r,met,cx,cy,cz,rad,h){put(mc,col,r,met,[cx,cy,cz],0,[rad,h,rad]);}
