  box(STONE,0.75,0,0,D*0.66/2,-4.12,2.2,D*0.66,0.36);box(STONE,0.75,0,0,D*0.33/2,-3.82,2.2,D*0.33,0.3);
  box(CARPET,0.95,0,0,D*0.66+0.012,-4.12,1.2,0.024,0.36);box(CARPET,0.95,0,0,D*0.33+0.012,-3.82,1.2,0.024,0.3);
