function devOpen(){if(!devOpen.ok){openCard('<h2>開發者選項</h2><form id="pw" class="tf"><input id="pwi" type="password" placeholder="請輸入密碼" autocomplete="off"><button class="b1">進入</button></form><p class="sub" id="pwm"></p><div class="acts"><button class="b2" onclick="closeCard()">取消</button></div>');
    $('pw').onsubmit=function(e){e.preventDefault();if($('pwi').value==='apple'){devOpen.ok=true;devOpen();}else $('pwm').textContent='密碼不對。';};return;}
  var h='<h2>開發者選項</h2><p class="sub" id="aiState"></p>';
  DEVSPEC.forEach(function(g,gi){h+='<details'+(gi<2?' open':'')+'><summary>'+g[0]+'</summary>';g[1].forEach(function(it){h+='<div class="row"><label for="dv_'+it[0]+'">'+it[1]+'</label><input id="dv_'+it[0]+'" type="range" min="'+it[2]+'" max="'+it[3]+'" step="'+it[4]+'" value="'+CFG[it[0]]+'"><output id="dvo_'+it[0]+'">'+CFG[it[0]]+'</output></div>';});h+='</details>';});
  h+='<details open><summary>AI 模型等級</summary><div class="row"><label for="dvTier">出題模型</label><select id="dvTier">'+['quick','default','complex'].map(function(t){return '<option'+(CFG.tier===t?' selected':'')+'>'+t+'</option>';}).join('')+'</select></div></details>';
  h+='<details open><summary>進度與指標</summary><div class="row"><label for="dvCh">跳到章節</label><select id="dvCh">'+SYL.map(function(s,i){return '<option value="'+i+'"'+(i===chIdx()?' selected':'')+'>第'+(i+1)+'章 '+s.t+'</option>';}).join('')+'</select></div>'+
    [0,1,2,3].map(function(i){return '<div class="row"><label for="dvI'+i+'">'+IND[i]+'</label><input id="dvI'+i+'" type="range" min="1" max="100" step="1" value="'+G.ind[i]+'"><output id="dvIo'+i+'">'+G.ind[i]+'</output></div>';}).join('')+
    '<div class="acts"><button class="b2" id="dvMorning">快轉到卯時（早朝）</button><button class="b2" id="dvNext">直接跳到下一天</button><button class="b2" id="dvLook">兔子外觀／環境設定</button><button class="b2" id="dvReset">參數全部重設</button><button class="b2" id="dvNew">重新開始遊戲</button></div></details>';
  h+='<div class="acts"><button class="b1" onclick="closeCard()">關閉</button></div>';openCard(h,'dev');aiBadge();
  DEVSPEC.forEach(function(g){g[1].forEach(function(it){var e=$('dv_'+it[0]);e.oninput=function(){CFG[it[0]]=+e.value;$('dvo_'+it[0]).textContent=e.value;saveCfg();applyCfg();aiBadge();};});});
  $('dvTier').onchange=function(e){CFG.tier=e.target.value;saveCfg();};
  $('dvCh').onchange=function(e){G.day=+e.target.value*CFG.daysPerCh;G.hr=4.2;G.court='wait';G.qToday=0;saveG();hud();toast('已跳到第'+(+e.target.value+1)+'章');};
  [0,1,2,3].forEach(function(i){$('dvI'+i).oninput=function(e){G.ind[i]=+e.target.value;$('dvIo'+i).textContent=e.target.value;hud();saveG();};});
  $('dvMorning').onclick=function(){G.hr=5.01;G.court='wait';closeCard();toast('卯時到了');};$('dvNext').onclick=function(){closeCard();nextDay();};
  $('dvLook').onclick=function(){closeCard();$('sheet').hidden=false;};
  $('dvReset').onclick=function(){for(var k in CFG_DEF)CFG[k]=CFG_DEF[k];saveCfg();applyCfg();devOpen();};
  $('dvNew').onclick=function(){G=newGame();saveG();closeCard();restart();};}
// ---------- 啟動 ----------
function gameInit(){initActors();initAI();hud();
  // 卡片裡的按鈕用到的函式（inline onclick 需要全域）與測試用的入口
  window.closeCard=closeCard;window.courtEnd=courtEnd;window.showNotes=showNotes;window.dianShi=dianShi;window.restart=restart;
  window.__C={PL:PL,EU:EU,PR:PR,MIN:MIN,hero:hero,cam:cam,G:function(){return G;},phase:phase,CFG:CFG,UI:UI,courtStart:courtStart,saveG:function(){saveG();},checkEnd:function(){return checkEnd();},act:act,AFT:AFT,RAB:RAB,jian:jian,royalMenu:royalMenu,VIEW:VIEW,quest:quest,R0:R0,dianShi:dianShi,state:state};
  $('bNotes').onclick=showNotes;$('bMenu').onclick=royalMenu;$('bView').onclick=viewToggle;$('cardMin').onclick=function(){$('card').classList.toggle('min');};R0();
  if(G.court==='on'&&!G.over){UI.mode='court';courtSeat();setTimeout(courtNext,600);}$('bDev').onclick=devOpen;$('cardX').onclick=function(){if(UI.mode==='court'&&G.court==='on')return toast('早朝進行中，請先處理完奏事');closeCard();UI.mode=G.court==='on'?'court':'free';};
  $('sheetX').onclick=function(){$('sheet').hidden=true;};
  if(G.over){checkEnd()||ending(0);}
  else if(G.day===0&&G.qTotal===0)openCard('<h2>大唐早朝・行政學</h2><p class="court">奴才給皇上請安，皇上萬福金安。</p><p>今天是貞觀元年第一天。每天卯時要上早朝，大臣會奏報十件沒有完美解的政務難題。你的每一個決定，都會牽動國家的四大指標：</p><p>'+INDI.map(function(x,i){return x+' '+IND[i];}).join('<br>')+'</p><p>任何一項歸零，王朝就會覆滅。每四天學完一章行政學，全部十六章涵蓋國考範圍。每一題結束後，都有考點解密幫你準備申論題。</p><p class="sub">操作：左半邊拖曳移動、右半邊拖曳轉鏡頭、雙指縮放。靠近大臣、太子、太監可以交談，靠近白兔可以互動。</p><p class="court">請主子起駕。</p><div class="acts"><button class="b1" onclick="closeCard()">起駕</button></div>');}

// ==========================================================================
// 學習系統：殿試（有標準答案的選擇題）、考點地圖、申論練習
// ==========================================================================
function SQ(){if(!G.quiz)G.quiz={wrong:[],stat:{},day:-1,seen:{}};if(!G.quiz.seen)G.quiz.seen={};return G.quiz;}
// ---------- 殿試 ----------
var DS=null;
function dsPool(ch){var Q=SQ(),out=[],used={};
  function add(c,i){var k=c+':'+i;if(used[k]||!QUIZ[c]||!QUIZ[c][i])return;used[k]=1;var x=QUIZ[c][i];out.push({c:c,i:i,q:x[0],o:x[1],a:x[2],why:x[3]});}
  Q.wrong.slice(0,2).forEach(function(w){add(w.c,w.i);});               // 先重考答錯的題目
  var cur=QUIZ[ch]||[],idx=cur.map(function(_,i){return i;});
  idx.sort(function(a,b){return ((Q.seen[ch+':'+a]||0)-(Q.seen[ch+':'+b]||0))||(Math.random()-0.5);});  // 沒考過的優先
  idx.forEach(function(i){if(out.length<CFG.dsN)add(ch,i);});
  if(out.length<CFG.dsN){var prev=[];for(var c=0;c<ch;c++)(QUIZ[c]||[]).forEach(function(_,i){prev.push([c,i]);});   // 本章沒題目就複習前面章節
    prev.sort(function(){return Math.random()-0.5;}).forEach(function(p){if(out.length<CFG.dsN)add(p[0],p[1]);});}
  return out;}
function dsAI(ch){return ask('你是中華民國國家考試行政學的命題委員。請依「第'+(ch+1)+'章 '+SYL[ch].t+'」的範圍（'+SYL[ch].d.join('；')+'）出 '+CFG.dsN+' 題四選一選擇題，難度比照高普考，涵蓋不同考點，每題只有一個正確答案，解析用台灣繁體中文白話說明為什麼對、其他選項錯在哪。'+
  '只輸出 JSON：{"items":[{"q":"","o":["","","",""],"a":0,"why":""}]}').then(function(v){var it=(v&&v.items)||[];
  return it.filter(function(x){return x&&x.q&&x.o&&x.o.length===4&&x.a>=0&&x.a<4;}).slice(0,CFG.dsN).map(function(x){return {c:ch,i:-1,q:String(x.q),o:x.o.map(String),a:+x.a,why:String(x.why||'')};});});}
function dianShi(practice){var ch=chIdx(),pool=dsPool(ch);
  function go(list){if(!list.length){openCard('<h3>殿試</h3><p>這一章還沒有內建的殿試題目，AI 也沒有開啟。請在 Claude 裡開啟遊戲，或先複習奏摺匣。</p><div class="acts"><button class="b1" onclick="closeCard()">知道了</button></div>');return;}
    DS={list:list,k:0,ok:0,practice:!!practice,ch:ch};dsShow();}
  var own=(QUIZ[ch]||[]).length;
  if(!own&&aiOn()){openCard('<div class="wait"><div class="spin"></div><p>主考官正在出殿試題…</p></div>');
    dsAI(ch).then(function(l){go(l.length?l:pool);},function(){go(pool);});return;}
  go(pool);}
function dsShow(){var d=DS,x=d.list[d.k];
  var h='<div class="who">殿試・第'+cnum(d.k+1)+'題／共'+cnum(d.list.length)+'題'+(x.c!==d.ch?'<span>（第'+cnum(x.c+1)+'章複習）</span>':'')+'</div>'+
    (d.k===0?'<p class="court">'+(d.practice?'皇上溫書，微臣隨侍。':'啟奏皇上，殿試開始，請陛下作答。')+'</p>':'')+
    '<p class="dsq">'+esc(x.q)+'</p><div class="ops">'+x.o.map(function(o,i){return '<button class="op" data-i="'+i+'"><b>'+'ABCD'[i]+'</b>'+esc(o)+'</button>';}).join('')+'</div>';
  openCard(h,'q');[].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){b.onclick=function(){dsAns(+b.dataset.i);};});}
function dsAns(i){var d=DS,x=d.list[d.k],Q=SQ(),ok=i===x.a,key=x.c+':'+x.i;if(ok)d.ok++;
  if(x.i>=0){Q.seen[key]=(Q.seen[key]||0)+1;Q.wrong=Q.wrong.filter(function(w){return w.c+':'+w.i!==key;});if(!ok)Q.wrong.unshift({c:x.c,i:x.i});Q.wrong=Q.wrong.slice(0,40);}
  var st=Q.stat[x.c]=Q.stat[x.c]||{n:0,ok:0};st.n++;if(ok)st.ok++;saveG();
  [].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){var j=+b.dataset.i;b.disabled=true;if(j===x.a)b.classList.add('right');else if(j===i)b.classList.add('wrong');});
  var last=d.k>=d.list.length-1,box=document.createElement('div');
  box.innerHTML='<div class="res '+(ok?'good':'bad')+'"><b>'+(ok?'答對了！':'答錯了，正確答案是 '+'ABCD'[x.a]+'。')+'</b><p>'+esc(x.why)+'</p>'+(ok?'':'<p class="sub">這題已收進錯題本，之後的殿試會再考一次。</p>')+'</div><div class="acts"><button class="b1" id="dsN">'+(last?'看成績':'下一題')+'</button></div>';
  $('cardBody').appendChild(box);$('dsN').onclick=function(){if(last)dsEnd();else{d.k++;dsShow();}};box.scrollIntoView({block:'nearest'});}
function dsEnd(){var d=DS,Q=SQ(),n=d.list.length,r=d.ok/n,reward=!d.practice&&Q.day!==G.day,dd=[0,0,0,0];
  Q.last=d.ok+'／'+n;Q.lastDay=G.day;if(d.ok===n)Q.perfect=1;if(!d.practice)R0().dsDay=G.day;if(reward){Q.day=G.day;dd=r>=0.8?[1,2,3,2]:r>=0.6?[0,1,1,1]:r<0.4?[0,0,-2,-1]:[0,0,0,0];addInd(dd,1);saveG();}
  var msg=r>=0.8?'皇上學養深厚，群臣嘆服。':r>=0.6?'皇上大致掌握，微臣再呈幾處要點。':'此章尚待溫習，請皇上打開奏摺匣再讀一遍。';
  openCard('<h3>殿試成績</h3><p class="big">'+d.ok+' ／ '+n+'</p><p class="court">'+msg+'</p>'+(reward?'<div>'+dstr(dd)+'</div>':'<p class="sub">'+(d.practice?'練習模式不影響指標。':'今天已經考過殿試，這次不計入指標。')+'</p>')+
    '<p class="sub">錯題本目前有 '+Q.wrong.length+' 題。</p><div class="acts"><button class="b1" onclick="closeCard()">退下</button><button class="b2" id="dsAgain">再考一輪</button><button class="b2" onclick="showNotes()">奏摺匣</button></div>');
  $('dsAgain').onclick=function(){dianShi(true);};}
// ---------- 考點地圖 ----------
function kpTokens(s){return s.split(/[：；、，,（）()／\/]/).map(function(t){return t.trim();}).filter(function(t){return t.length>=2&&t!=='vs';});}
function kpMatch(t,txt){if(txt.indexOf(t)>=0)return true;var lat=t.match(/[A-Za-z][A-Za-z&.]{2,}/g);if(lat&&lat.some(function(w){return w!=='vs'&&txt.indexOf(w)>=0;}))return true;
  var zh=t.replace(/[A-Za-z0-9&.\s—–-]/g,'');return zh.length>=4&&txt.indexOf(zh.slice(0,4))>=0;}
function kpChapter(c){var txt=G.notes.filter(function(n){return n.ch===c;}).map(function(n){var e=n.exam||{};return [n.title,(n.tp||[]).join(' '),e.core,e.masters,[].concat(e.keys||[]).join(' ')].join(' ');}).join(' ');
  var all=[],got=0;SYL[c].d.forEach(function(f){kpTokens(f).forEach(function(t){var m=!!txt&&kpMatch(t,txt);all.push([t,m]);if(m)got++;});});return {all:all,got:got};}
function studyMapHtml(){var Q=SQ(),h='<details><summary>🗺 考點地圖（金色＝已學過）</summary><p class="sub">依早朝題目涵蓋到的考點自動標記，殿試答對率另列。</p>';
  SYL.forEach(function(s,c){var k=kpChapter(c),st=Q.stat[c],pct=k.all.length?Math.round(k.got/k.all.length*100):0;
    h+='<div class="kpc'+(c===chIdx()?' cur':'')+'"><b>第'+cnum(c+1)+'章 '+esc(s.t)+'</b><span class="sub"> 涵蓋 '+pct+'%'+(st?'・殿試答對 '+st.ok+'／'+st.n:'')+'</span><div class="kps">'+
      k.all.map(function(a){return '<i class="'+(a[1]?'on':'')+'">'+esc(a[0])+'</i>';}).join('')+'</div></div>';});
  if(Q.wrong.length)h+='<p class="sub">錯題本：'+Q.wrong.length+' 題（殿試時會優先重考）</p>';
  return h+'<div class="acts"><button class="b2" id="dsPrac">練習殿試（不計分）</button></div></details>';}
// ---------- 申論練習 ----------
function essay(ni){var obj=typeof ni==='object',n=obj?ni:G.notes[ni],lk='court_es_'+(obj?'q'+ni.title:ni);if(!n)return;var e=n.exam||{};
  var h='<h3>申論練習</h3><p class="sub">題目來源：'+esc(n.title)+'</p><p class="dsq">試以「'+esc((n.tp||[]).join('、')||n.title)+'」為核心，結合本題情境，論述其理論內涵、實務困境與因應之道。</p>'+
    '<textarea id="esT" rows="9" placeholder="在這裡寫下你的答案（建議 300～600 字）"></textarea><p class="sub" id="esC">0 字</p>'+
    '<div class="acts"><button class="b1" id="esGo">交卷批改</button><button class="b2" id="esRef">先看答題架構</button><button class="b2" onclick="showNotes()">回奏摺匣</button></div><div id="esR"></div>';
  openCard(h,'notes');var T=$('esT');try{T.value=localStorage.getItem(lk)||'';}catch(x){}
  T.oninput=function(){$('esC').textContent=T.value.replace(/\s/g,'').length+' 字';try{localStorage.setItem(lk,T.value);}catch(x){}};T.oninput();
  $('esRef').onclick=function(){$('esR').innerHTML='<div class="res"><b>答題架構</b><p>'+esc(e.essay)+'</p><b>理論核心</b><p>'+esc(e.core)+'</p><p>'+[].concat(e.keys||[]).map(function(k){return '<span class="key">'+esc(k)+'</span>';}).join('')+'</p></div>';};
  $('esGo').onclick=function(){var a=T.value.trim();if(a.length<30){toast('請至少寫 30 字再交卷');return;}
    R0().essayN++;var keys=[].concat(e.keys||[]),hit=keys.filter(function(k){return kpMatch(k,a)||kpTokens(k).some(function(t){return a.indexOf(t)>=0;});});
    var off='<div class="res"><b>關鍵字命中 '+hit.length+'／'+keys.length+'</b><p>'+keys.map(function(k){return '<span class="key'+(hit.indexOf(k)>=0?' on':'')+'">'+(hit.indexOf(k)>=0?'✓ ':'✗ ')+esc(k)+'</span>';}).join('')+'</p><p class="sub">參考架構：'+esc(e.essay)+'</p></div>';
    if(!aiOn()){$('esR').innerHTML=off+'<p class="sub">AI 未開啟，目前只做關鍵字比對。在 Claude 裡開啟遊戲可獲得完整批改。</p>';return;}
    $('esR').innerHTML='<div class="wait"><div class="spin"></div><p>閱卷官批改中…</p></div>';
    ask('你是中華民國高普考行政學的閱卷委員。請批改考生申論答案，滿分 25 分。\n題目情境：'+n.title+'；考點：'+(n.tp||[]).join('、')+'。\n參考要點：'+e.core+'\n關鍵字：'+keys.join('、')+'\n參考架構：'+e.essay+'\n考生答案：'+a+'\n'+
      '請用台灣繁體中文白話，第一句與最後一句用古代臣子對皇帝的恭敬語氣（稱「皇上」，自稱「微臣」）。只輸出 JSON：{"score":0,"good":"做得好的地方","miss":"缺漏或錯誤","better":"改進建議與一段示範段落"}').then(function(v){
      $('esR').innerHTML='<div class="res good"><b>得分：'+Math.max(0,Math.min(25,Math.round(+v.score||0)))+'／25</b><p><b>優點：</b>'+esc(v.good)+'</p><p><b>缺漏：</b>'+esc(v.miss)+'</p><p><b>改進：</b>'+esc(v.better)+'</p></div>'+off;},
      function(){$('esR').innerHTML=off+'<p class="sub">AI 批改暫時失敗，先提供關鍵字比對。</p>';});};}
function studyBind(){var p=$('dsPrac');if(p)p.onclick=function(){dianShi(true);};
  [].forEach.call(document.querySelectorAll('#cardBody [data-es]'),function(b){b.onclick=function(){essay(+b.dataset.es);};});}

// ==========================================================================
// 早朝儀式：皇上登上丹陛御座→太監唱「皇上駕到」→百官躬身三呼萬歲→皇上下旨開始奏事
// 奏事時出班的大臣上前一步；皇上決定後，相關大臣會有反應；退朝時太監唱「退朝」
// 第一人稱御座視角：從丹陛上俯視群臣，可拖曳環顧，可切換回第三人稱
// ==========================================================================
function sub(who,txt,ms){var e=$('sub');if(!e)return;e.innerHTML=(who?'<b>'+esc(who)+'</b>':'')+esc(txt);e.hidden=false;clearTimeout(sub.h);sub.h=setTimeout(function(){e.hidden=true;},ms||3200);}
// ---------- 視角 ----------
var VIEW={fp:false};
function fpOn(){VIEW.fp=true;PL.hidden=true;window.__FOV=CFG.fpFov;cam.theta=Math.PI;cam.phi=1.3;cam.hold=2;}
function fpOff(){VIEW.fp=false;PL.hidden=false;window.__EYE=null;window.__AT=null;window.__FOV=null;cam.theta=0.35;cam.hold=3;}
function viewUpdate(){var b=$('bView');if(b)b.hidden=G.court!=='on';
  if(!VIEW.fp){window.__EYE=null;window.__AT=null;return;}
  var e=[PL.pos[0],(PL.y||0)+1.42*CFG.hPl/152,PL.pos[2]+0.12],s=Math.sin(cam.phi);
  // 用鏡頭的 theta／phi 當視線方向：右半邊拖曳就能環顧朝堂
  var d=[-s*Math.sin(cam.theta),-Math.cos(cam.phi),-s*Math.cos(cam.theta)];
  window.__EYE=e;window.__AT=[e[0]+d[0],e[1]+d[1],e[2]+d[2]];}
function viewToggle(){if(VIEW.fp){fpOff();window.__CT=[0,0,LOC.throne[1]+2.4];cam.theta=Math.PI+0.12;cam.phi=0.98;cam.r=7.4;cam.hold=2;}else{window.__CT=null;fpOn();}}
// ---------- 儀式 ----------
var CER={spk:null,busy:false};
function bowAll(a,ms){MIN.forEach(function(m){m.bow=a;});EU.bow=a*0.8;if(ms)setTimeout(function(){MIN.forEach(function(m){m.bow=0;});EU.bow=0;},ms);}
function ceremony(){CER.busy=true;UI.locked=true;
  sub('總管太監','皇上駕到——',2400);EU.bow=0.35;
  setTimeout(function(){bowAll(0.55);PR.once='salute';PR.play('salute',0.2);sub('文武百官','臣等叩見吾皇，吾皇萬歲，萬歲，萬萬歲！',3400);},1700);
  setTimeout(function(){CER.busy=false;cerOrder();},4300);}
function cerOrder(){openCard('<div class="who">金鑾殿<span>早朝・百官候旨</span></div><p class="court">群臣伏拜，殿內鴉雀無聲，等候聖諭。</p><p>皇上要怎麼開始今天的早朝？</p>'+
  '<div class="ops"><button class="op" id="co1"><b>旨</b>「眾卿平身，有事早奏。」</button><button class="op" id="co2"><b>問</b>「宰相，先奏天下大勢。」</button><button class="op" id="co3"><b>罷</b>「朕今日龍體欠安，罷朝。」</button></div>','q');
  $('co1').onclick=cerBegin;$('co2').onclick=cerBrief;
  $('co3').onclick=function(){openCard('<p class="court">奴才惶恐。</p><p>罷朝會讓政令延宕：民眾滿意度、官僚效能感、政治協調度都會下降，也會中斷連續臨朝的紀錄。</p><div class="acts"><button class="b1" id="cy">確定罷朝</button><button class="b2" id="cn">還是上朝吧</button></div>');
    $('cy').onclick=function(){bowAll(0);fpOff();courtEnd(true);};$('cn').onclick=cerOrder;};}
function cerBegin(){closeCard();UI.locked=true;bowAll(0);sub('總管太監','眾卿平身——有事出班啟奏，無事捲簾退朝！',2600);setTimeout(function(){courtNext();},1500);}
function cerBrief(){var I=G.ind,lo=I.indexOf(Math.min.apply(null,I)),hi=I.indexOf(Math.max.apply(null,I));
  var word=function(v){return v>=70?'穩固':v>=45?'尚可':v>=25?'吃緊':'危急';};
  openCard('<div class="who">'+esc(PEOPLE.m0.n)+'<span>奏報天下大勢</span></div><p class="court">啟奏皇上，臣謹將天下大勢稟明。</p>'+
    '<p>'+IND.map(function(n,i){return INDI[i]+' '+n+'：'+I[i]+'（'+word(I[i])+'）';}).join('<br>')+'</p>'+
    '<p>目前最需要留意的是<b>'+IND[lo]+'</b>；最穩的是'+IND[hi]+'。還有 '+G.pend.length+' 件先前決策的後續影響尚未浮現。</p>'+
    '<p>今日議題焦點：<b>'+esc(focus())+'</b>（第'+cnum(chIdx()+1)+'章 '+esc(SYL[chIdx()].t)+'）。</p><p class="court">伏乞聖裁。</p>'+
    '<div class="acts"><button class="b1" id="cb">「眾卿平身，開始奏事。」</button></div>','q');$('cb').onclick=cerBegin;}
// 奏事時，出班的大臣上前一步
function cerTarget(n,base){if(G.court!=='on'||CER.spk!==n)return base;var dx=LOC.throne[0]-base[0],dz=LOC.throne[1]-base[1],d=Math.hypot(dx,dz)||1;return [base[0]+dx/d*0.9,base[1]+dz/d*0.9];}
// 皇上裁決後，朝堂上的反應（數值變動最大的那一項，由主管的大臣回應）
var REACT={0:['m1','（皺眉）國庫恐怕撐不住啊……','戶部銀庫總算能鬆一口氣了。'],1:['pr','兒臣擔心百姓會失望……','百姓必定感念皇恩！'],2:['m2','（低聲）底下的官員怕是要怨了……','百官必定奮勉任事！'],3:['m0','（沉吟）朝中恐怕要起紛擾……','皇上聖明，朝局可安。']};
function cerReact(q,d){var spk=CER.spk;if(spk){spk.bow=0.45;setTimeout(function(){spk.bow=0;},1300);}
  var k=-1,mx=0;d.forEach(function(v,i){if(Math.abs(v)>mx&&REACT[i][0]!==q.sp){mx=Math.abs(v);k=i;}});
  if(k<0||mx<5)return '';var r=REACT[k],who=NPC.filter(function(n){return n.id===r[0];})[0],pos=d[k]>0,line=pos?r[2]:r[1];
  if(who){if(pos){who.bow=0.4;setTimeout(function(){who.bow=0;},1400);}else if(who.kind==='war')who.play('hurtL',0.15);}
  setTimeout(function(){sub(PEOPLE[r[0]].n,line,3000);},400);
  return '<h3>【朝堂反應】</h3><p>'+esc(PEOPLE[r[0]].n)+'：'+esc(line)+'</p>';}
function cerEnd(){sub('總管太監','退朝——',2200);bowAll(0.5,1600);PR.once='salute';PR.play('salute',0.2);CER.spk=null;fpOff();}

// ==========================================================================
// 引導與皇權：任務指引（金色指標＋小地圖）、太監催駕、新手提示、成就、
// 御用選單（擺駕、召見、詔令、傳膳、歇息、起居注、存讀檔）、每日總結
// ==========================================================================
function R0(){if(!G.rpg)G.rpg={tut:{},ach:{},dec:{},decN:0,nag:{d:-1,n:0},streak:0,lastCourt:-9,rabN:0,talkN:0,essayN:0,dayStart:G.ind.slice(),dsDay:-1};return G.rpg;}
// ---------- 目前任務 ----------
function quest(){var ph=phase()[1],R=R0();if(G.over)return null;
  if(G.court==='on')return {t:'主持早朝：第 '+Math.min(G.qToday+1,CFG.qPerDay)+'／'+CFG.qPerDay+' 奏',tg:null};
  if(G.court==='wait'&&G.hr<7)return {t:G.hr<5?'寅時：梳洗更衣，準備前往金鑾殿':'卯時：登上金鑾殿御座，主持早朝',tg:LOC.throne};
  if(G.court==='done'&&R.dsDay!==G.day&&G.hr<11)return {t:'參加今日殿試（「御」→殿試）',tg:null};
  if(ph==='戌時')return {t:'戌時：到後宮探望白兔娘娘',tg:[hero.pos[0],hero.pos[2]]};
  if(ph==='亥時')return {t:'亥時：回寢宮就寢，結束今天',tg:LOC.bed};
  if(ph==='巳時'||ph==='未時')return {t:'可到中書省與大臣議事，或巡視宮苑',tg:LOC.office};
  if(ph==='申時')return {t:'申時：可出城逛大街市集，或到東宮看太子讀書',tg:null};
  return {t:'自由活動：巡視宮苑、與人交談、溫習奏摺',tg:null};}
var QT=0;
function rpgUpdate(dt){var R=R0();QT+=dt;var q=quest(),qe=$('quest');
  if(qe){qe.hidden=!q;if(q){var dd=q.tg?Math.round(Math.hypot(q.tg[0]-PL.pos[0],q.tg[1]-PL.pos[2])):0;qe.innerHTML='<b>任務</b>'+esc(q.t)+(q.tg&&dd>1?'<span>'+dd+' 步</span>':'');}}
  waypoint(q);if(CFG.minimap)minimap(q);else{var c=$('mmap');if(c)c.hidden=true;}
  nag();summonUpdate(dt);
  if(QT>1.5){QT=0;achCheck();tutorial();}}
// 畫面上的金色指標（目標在畫面外時，貼在邊緣並指向目標）
function waypoint(q){var e=$('wp'),VP=window.__VP;if(!e)return;if(!q||!q.tg||!VP||UI.locked||Math.hypot(q.tg[0]-PL.pos[0],q.tg[1]-PL.pos[2])<1.6){e.hidden=true;return;}
  var x=q.tg[0],y=1.4,z=q.tg[1],cx=VP[0]*x+VP[4]*y+VP[8]*z+VP[12],cy=VP[1]*x+VP[5]*y+VP[9]*z+VP[13],cw=VP[3]*x+VP[7]*y+VP[11]*z+VP[15];
  var sx=cx/Math.abs(cw||1e-3),sy=cy/Math.abs(cw||1e-3),behind=cw<0.05,W=innerWidth,H=innerHeight;if(behind){sx=-sx;sy=-1;}
  var off=behind||Math.abs(sx)>0.92||Math.abs(sy)>0.85,px,py,ang=0;
  if(off){var m=Math.max(Math.abs(sx)/0.88,Math.abs(sy)/0.78,1e-3);sx/=m;sy/=m;ang=Math.atan2(-sy,sx)*180/Math.PI;}
  px=(sx*0.5+0.5)*W;py=(0.5-sy*0.5)*H;e.hidden=false;e.style.left=px+'px';e.style.top=py+'px';e.className=off?'off':'';
  e.firstChild.style.transform=off?'rotate('+ang+'deg)':'';e.lastChild.textContent=Math.round(Math.hypot(x-PL.pos[0],z-PL.pos[2]))+' 步';}
// 小地圖：北方朝上，金色箭頭是皇上
function minimap(q){var c=$('mmap');if(!c)return;c.hidden=false;var g=c.getContext('2d'),S=c.width,k=S/22,o=S/2;g.clearRect(0,0,S,S);
  g.fillStyle='rgba(23,17,13,.72)';g.beginPath();g.arc(o,o,o-1,0,6.29);g.fill();g.strokeStyle='#a8863f';g.lineWidth=2;g.stroke();
  function P(x,z){return [o+x*k,o+z*k];}
  g.fillStyle='rgba(163,34,26,.55)';var a=P(-3.9,-6.4),b=P(3.9,1.0);g.fillRect(a[0],a[1],b[0]-a[0],b[1]-a[1]);
  g.font=(S/12|0)+'px serif';g.textAlign='center';g.textBaseline='middle';
  PLACES.forEach(function(p){var s=P(p[1][0],p[1][1]);g.fillStyle='#d8b25e';g.fillText(p[0][0],s[0],s[1]);});
  function dot(x,z,col,r){var s=P(x,z);g.fillStyle=col;g.beginPath();g.arc(s[0],s[1],r,0,6.29);g.fill();}
  MIN.forEach(function(m){dot(m.pos[0],m.pos[2],'#8fb3e8',S/40);});dot(PR.pos[0],PR.pos[2],'#7fcf8f',S/40);dot(EU.pos[0],EU.pos[2],'#c49be0',S/40);dot(hero.pos[0],hero.pos[2],'#f4a6c0',S/40);
  if(q&&q.tg){var t=P(q.tg[0],q.tg[1]);g.strokeStyle='#ffe08a';g.lineWidth=2;g.beginPath();g.arc(t[0],t[1],S/22,0,6.29);g.stroke();}
  var s=P(PL.pos[0],PL.pos[2]);g.save();g.translate(s[0],s[1]);g.rotate(-PL.yaw+Math.PI);g.fillStyle='#ffd34d';g.beginPath();g.moveTo(0,-S/16);g.lineTo(S/26,S/26);g.lineTo(-S/26,S/26);g.closePath();g.fill();g.restore();}
// ---------- 太監催駕 ----------
function nag(){var R=R0(),N=R.nag;if(N.d!==G.day){N.d=G.day;N.n=0;}if(G.over||G.court!=='wait')return;
  if(N.n<1&&G.hr>=4.3){N.n=1;sub(PEOPLE.eu.n,'主子萬福。該起身更衣了，卯時要上朝，奴才在前頭引路。',4200);}
  if(N.n<2&&G.hr>=5.5){N.n=2;sub(PEOPLE.eu.n,'主子，卯時已到，文武百官都在金鑾殿候駕了。',4200);toast('📯 百官候駕：跟著金色指標走到御座');}
  if(N.n<3&&G.hr>=6.3&&!UI.locked){N.n=3;openCard('<div class="who">'+esc(PEOPLE.eu.n)+'<span>催駕</span></div><p class="court">主子，奴才斗膽……</p><p>百官已經等了一個多時辰，再不上朝，大臣們就要散了。罷朝會讓民眾滿意度、官僚效能感、政治協調度下降。</p><p class="court">請主子示下。</p>'+
    '<div class="acts"><button class="b1" id="ng1">擺駕金鑾殿</button><button class="b2" id="ng2">朕自己走過去</button></div>');
    $('ng1').onclick=function(){closeCard();courtStart();};$('ng2').onclick=function(){closeCard();};}}
// ---------- 新手提示 ----------
var TUT=[['move',function(){return !UI.locked;},'👣 左半邊螢幕拖曳可以走動；金色指標與右上小地圖會指引任務方向。'],
  ['near',function(){return !!NEAR&&!UI.locked;},'💬 靠近人物時，右下角會出現交談按鈕。'],
  ['menu',function(){return G.court==='done'&&!UI.locked;},'👑 點右上角「御」：擺駕、召見、頒布詔令、殿試、存檔都在這裡。'],
  ['notes',function(){return G.qTotal>=3&&!UI.locked;},'📜 「奏摺匣」收錄每一題的考點，還有考點地圖與申論練習。']];
function tutorial(){var R=R0();for(var i=0;i<TUT.length;i++){var t=TUT[i];if(!R.tut[t[0]]){if(t[1]()){R.tut[t[0]]=1;toast(t[2],5200);saveG();}return;}}}
// ---------- 成就 ----------
var ACH=[['first','初登大寶','第一次主持早朝',function(R){return G.qTotal>=1;}],['q50','勤政愛民','累計處理 50 件奏事',function(){return G.qTotal>=50;}],
  ['streak','宵衣旰食','連續 7 天臨朝',function(R){return R.streak>=7;}],['ds','金榜題名','殿試全部答對',function(){return !!(G.quiz&&G.quiz.perfect);}],
  ['all70','天下大治','四大指標同時達到 70',function(){return G.ind.every(function(v){return v>=70;});}],['ch','學成一章','完成一整章（'+CFG.daysPerCh+' 天）',function(){return G.day>=CFG.daysPerCh;}],
  ['dec','乾綱獨斷','頒布 5 道詔令',function(R){return R.decN>=5;}],['essay','文章經國','第一次交出申論',function(R){return R.essayN>=1;}],
  ['rab','後宮和睦','與白兔娘娘互動 10 次',function(R){return R.rabN>=10;}],['talk','虛心求教','與人交談 5 次',function(R){return R.talkN>=5;}],
  ['na','從諫如流','採納大臣直諫 3 次',function(R){return (R.naN||0)>=3;}],['daily','日理萬機','完成全部每日目標 3 天',function(R){return (R.dailyAll||0)>=3;}]];
function achCheck(){var R=R0();ACH.forEach(function(a){if(!R.ach[a[0]]&&a[3](R)){R.ach[a[0]]=G.day+1;toast('🏆 成就解鎖：'+a[1]+'——'+a[2],5000);saveG();}});}
// ---------- 召見 ----------
var SUMMON={who:null};
function summon(n){closeCard();if(n===hero){RAB.sum=true;RAB.tg=null;RAB.wait=0;toast('已傳白兔娘娘伴駕');return;}SUMMON.who=n;toast('已傳'+PEOPLE[n.id].n+'覲見');}
function summonUpdate(dt){var n=SUMMON.who;if(!n)return;var tx=PL.pos[0]+Math.sin(PL.yaw)*1.5,tz=PL.pos[2]+Math.cos(PL.yaw)*1.5;
  if(walkTo(n,tx,tz,dt,Math.hypot(tx-n.pos[0],tz-n.pos[2])>3,0.5)){faceTo(n,PL.pos[0],PL.pos[2],dt);if(!UI.locked){SUMMON.who=null;talkTo(n);}}}
// ---------- 詔令（皇權）：每道詔令都對應一個行政學概念，各有冷卻天數 ----------
var DECREE=[['shemian','大赦天下',[-2,7,-2,-4],'恩赦是象徵性政治：短期提升民心，但削弱法律的嚇阻與課責，辦案的官員也會覺得心血白費。'],
  ['jianfu','減免賦稅',[-8,7,0,1],'還稅於民能提高滿意度，但財政韌性下降；這正是 Wildavsky 預算政治中「花錢者」與「守財者」的拉鋸。'],
  ['shangci','賞賜百官',[-5,-1,6,3],'賞賜能提振士氣，但若與績效無關，依 Herzberg 二因子理論只是保健因素，只能消除不滿、無法真正激勵。'],
  ['enke','加開恩科',[-3,3,4,-2],'擴大考試取才落實功績制、增加社會流動與代表性，但既有官員擔心升遷被稀釋。'],
  ['zuiji','下罪己詔',[0,6,0,-4],'領導者公開承擔責任是政治課責，能重建正當性與信任，但也讓政敵抓到把柄。'],
  ['xunxing','巡幸地方',[-5,5,-1,2],'親自巡視是「走動式管理」，提升回應性並掌握基層資訊，但耗費財政，朝政也暫時由他人代理。'],
  ['zhengsu','整肅吏治',[0,4,3,-6],'派御史整肅貪腐強化外部課責（Finer），但官僚會出現防衛性行政，朝中派系也會反彈。'],
  ['qiuxian','下詔求賢',[-2,2,3,1],'廣開言路、徵求民間人才，接近開放政府與公民參與的精神，但篩選需要成本。']];
var DEC_CD=4;
function decreeMenu(){var R=R0();openCard('<h2>頒布詔令</h2><p class="sub">皇權在手，但每道詔令都有代價。同一道詔令 '+DEC_CD+' 天內只能頒布一次。</p><div class="ops">'+
  DECREE.map(function(d,i){var left=R.dec[d[0]]!=null?R.dec[d[0]]+DEC_CD-G.day:0;return '<button class="op" data-d="'+i+'"'+(left>0?' disabled':'')+'><b>詔</b>'+d[1]+'<small>'+(left>0?'（'+left+' 天後可再頒布）':dstr(d[2].map(function(x){return Math.round(x*CFG.mult);})))+'</small></button>';}).join('')+
  '</div><div class="acts"><button class="b2" id="dm">返回</button></div>','q');$('dm').onclick=royalMenu;
  [].forEach.call(document.querySelectorAll('#cardBody [data-d]'),function(b){b.onclick=function(){decree(+b.dataset.d);};});}
function decree(i){var d=DECREE[i],R=R0(),dd=d[2].map(function(x){return Math.round(x*CFG.mult);});R.dec[d[0]]=G.day;R.decN++;addInd(dd,1);saveG();hud();
  sub(PEOPLE.eu.n,'奉天承運皇帝，詔曰：'+d[1]+'。欽此——',3000);
  if(checkEnd())return;openCard('<div class="who">詔令<span>'+d[1]+'</span></div><p class="court">奉天承運皇帝，詔曰……</p><h3>【數值變動】</h3><div>'+dstr(dd)+'</div><h3>🎓【行政學觀點】</h3><div class="exam"><p>'+esc(d[3])+'</p></div><p class="court">臣等遵旨。</p><div class="acts"><button class="b1" onclick="closeCard()">退下</button></div>');}
