function schKey(n){return n.replace(/^[A-Z]{1,2}\.\s*/,'').replace(/（.*）/,'').trim();}
function schRel(a,b){a=schKey(a);b=schKey(b);return a.indexOf(b)>=0||b.indexOf(a)>=0;}
function schQ(k){var s=SCH[k],same=SCH.filter(function(x){return !schRel(x[0],s[0])&&x[1]!==s[1];}),pool=same.filter(function(x){return Math.abs(x[2]-s[2])<=1;});
  if(pool.length<3)pool=same;pool=pool.slice().sort(function(){return Math.random()-0.5;});
  var rev=Math.random()<0.4,opts=[],seen={};opts.push(rev?s[1]:s[0]);seen[opts[0]]=1;
  for(var i=0;i<pool.length&&opts.length<4;i++){var v=rev?pool[i][1]:pool[i][0];if(!seen[v]){seen[v]=1;opts.push(v);}}
  var ord=[0,1,2,3].sort(function(){return Math.random()-0.5;}),o=ord.map(function(j){return opts[j];});
  return {c:s[2],i:-1,s:k,q:rev?'「'+s[0]+'」提出或主張的是：':'「'+s[1]+'」是哪一位（些）學者提出的？',o:o,a:ord.indexOf(0),why:s[0]+'：'+s[1]+'（第'+cnum(s[2]+1)+'章 '+SYL[s[2]].t+'）。'};}
function quizQ(c,i){var x=QUIZ[c][i];return {c:c,i:i,q:x[0],o:x[1],a:x[2],why:x[3]};}
function acHas(c){return !!(BANK[c+'-0']||QUIZ[c]);}
// ---------------- 書院首頁 ----------------
function academy(tab){tab=tab||'home';var h='<h2>📚 書院</h2><div class="grid tabs">'+[['home','學習報告'],['lec','章節講義'],['mock','模擬測驗'],['wrong','錯題本'],['sch','學者速查']].map(function(t){
  return '<button class="b2'+(t[0]===tab?' on':'')+'" data-ac="'+t[0]+'">'+t[1]+'</button>';}).join('')+'</div><div id="acB"></div>';
  openCard(h,'notes acad');[].forEach.call(document.querySelectorAll('[data-ac]'),function(b){b.onclick=function(){academy(b.dataset.ac);};});
  ({home:acHome,lec:acLec,mock:acMock,wrong:acWrong,sch:acSch})[tab]();}
function acHome(){var Q=SQ(),rows='',weak=null,wv=2;
  SYL.forEach(function(s,c){if(!acHas(c))return;var st=Q.stat[c]||{n:0,ok:0},seen=G.notes.filter(function(n){return n.ch===c;}).length,kp=kpChapter(c),pct=kp.all.length?Math.round(kp.got/kp.all.length*100):0;
    var acc=st.n?Math.round(st.ok/st.n*100):null;if(st.n>=5&&st.ok/st.n<wv){wv=st.ok/st.n;weak=c;}
    rows+='<tr><td>'+cnum(c+1)+'</td><td>'+esc(s.t)+'</td><td>'+seen+'／40</td><td>'+pct+'%</td><td>'+(acc===null?'—':acc+'%（'+st.n+'題）')+'</td></tr>';});
  var hist=(Q.mock||[]).slice(-5).map(function(m){return '<span class="key">第'+cnum(m.d+1)+'天 '+m.s+' 分</span>';}).join('');
  $('acB').innerHTML='<p class="sub">全部章節都能在這裡自由複習，不受早朝進度限制；書院裡的練習不影響國家指標。</p>'+
    '<div class="tw"><table class="rep"><tr><th>章</th><th>主題</th><th>早朝已處理</th><th>考點涵蓋</th><th>選擇題答對率</th></tr>'+rows+'</table></div>'+
    (weak!==null?'<div class="res bad"><b>建議加強：第'+cnum(weak+1)+'章 '+esc(SYL[weak].t)+'</b><p>答對率 '+Math.round(wv*100)+'%，是目前最弱的一章。</p><div class="acts"><button class="b1" id="acWeak">針對這章測驗</button><button class="b2" id="acWeakL">讀講義</button></div></div>':'<p class="sub">至少作答 5 題後，會在這裡標出最需要加強的章節。</p>')+
    (hist?'<h3>最近的模擬測驗</h3><p>'+hist+'</p>':'')+'<p class="sub">錯題本：選擇題 '+Q.wrong.length+' 題、學者題 '+(Q.sw||[]).length+' 題。</p>';
  if(weak!==null){$('acWeak').onclick=function(){mockStart([weak],20);};$('acWeakL').onclick=function(){acLec(weak);};}}
// ---------------- 章節講義 ----------------
function acLec(c){if(c==null){$('acB').innerHTML='<p class="sub">選一章，可看每一題的背景、四個選項的理論說明、考點與申論架構。</p><div class="grid">'+SYL.map(function(s,i){
    return '<button class="b2" data-lc="'+i+'"'+(acHas(i)?'':' disabled')+'>'+cnum(i+1)+'・'+esc(s.t)+(acHas(i)?'':'（尚未收錄）')+'</button>';}).join('')+'</div>';
    [].forEach.call(document.querySelectorAll('[data-lc]'),function(b){b.onclick=function(){acLec(+b.dataset.lc);};});return;}
  var h='<h3>第'+cnum(c+1)+'章 '+esc(SYL[c].t)+'</h3>';
  for(var d=0;d<4;d++){var L=BANK[c+'-'+d]||[];if(!L.length)continue;h+='<details'+(d===0?' open':'')+'><summary>第'+cnum(d+1)+'天：'+esc((SYL[c].d[d]||'').split('：')[0])+'</summary><p class="sub">'+esc(SYL[c].d[d]||'')+'</p><div class="lst">'+
    L.map(function(q,i){return '<button class="b2" data-lq="'+d+'-'+i+'">'+(i+1)+'. '+esc(q.title)+'</button>';}).join('')+'</div></details>';}
  h+='<div class="acts"><button class="b1" id="lcT">本章模擬測驗</button><button class="b2" id="lcB">回章節列表</button></div>';
  $('acB').innerHTML=h;$('lcT').onclick=function(){mockStart([c],20);};$('lcB').onclick=function(){acLec();};
  [].forEach.call(document.querySelectorAll('[data-lq]'),function(b){b.onclick=function(){var p=b.dataset.lq.split('-');acQ(c,+p[0],+p[1]);};});}
function acQ(c,d,i){var q=BANK[c+'-'+d][i],e=q.exam||{};
  var h='<h3>'+esc(q.title)+'</h3><p class="sub">第'+cnum(c+1)+'章・第'+cnum(d+1)+'天・第'+(i+1)+'題</p><p>'+esc(q.bg)+'</p><p class="court">'+esc(q.ev)+'</p><p>'+(q.tp||[]).map(function(t){return '<span class="key">'+esc(t)+'</span>';}).join('')+'</p>'+
    '<h3>四個選項的理論說明</h3>'+q.op.map(function(o,j){return '<div class="res"><b>'+'ABCD'[j]+'. '+esc(o.t)+'</b><p>'+esc(o.why)+'</p></div>';}).join('')+
    '<h3>🎓 考點解密</h3><div class="exam"><p>'+esc(e.core)+'</p><p class="sub">出處：'+esc(e.masters)+'</p><p>'+[].concat(e.keys||[]).map(function(k){return '<span class="key">'+esc(k)+'</span>';}).join('')+'</p><p><b>申論架構：</b>'+esc(e.essay)+'</p></div>'+
    '<div class="acts"><button class="b1" id="qEs">寫申論練習</button><button class="b2" id="qPrev"'+(i>0?'':' disabled')+'>上一題</button><button class="b2" id="qNext"'+(i<BANK[c+'-'+d].length-1?'':' disabled')+'>下一題</button><button class="b2" id="qBack">回本章</button></div>';
  $('acB').innerHTML=h;$('cardBody').scrollTop=0;
  $('qEs').onclick=function(){essay({title:q.title,tp:q.tp,exam:e,ch:c});};$('qBack').onclick=function(){acLec(c);};
  $('qPrev').onclick=function(){acQ(c,d,i-1);};$('qNext').onclick=function(){acQ(c,d,i+1);};}
// ---------------- 模擬測驗 ----------------
var MK=null;
function acMock(){var cur=chIdx(),opts=SYL.map(function(s,i){return acHas(i)?'<label class="chk"><input type="checkbox" value="'+i+'"'+(i<=cur?' checked':'')+'> '+cnum(i+1)+' '+esc(s.t)+'</label>':'';}).join('');
  $('acB').innerHTML='<p class="sub">比照測驗題型：四選一、一題一分，全部作答完才公布答案。題目混合「殿試題」與「學者—理論配對題」。</p>'+
    '<h3>範圍</h3><div class="chks">'+opts+'</div><div class="acts"><button class="b2" id="mkAll">全選</button><button class="b2" id="mkCur">只選已學過的章</button></div>'+
    '<h3>題數</h3><div class="grid"><button class="b2" data-mn="10">10 題（約 10 分鐘）</button><button class="b1" data-mn="25">25 題（約 25 分鐘）</button><button class="b2" data-mn="50">50 題（約 50 分鐘）</button></div>';
  var boxes=function(){return [].slice.call(document.querySelectorAll('.chks input'));};
  $('mkAll').onclick=function(){boxes().forEach(function(b){b.checked=true;});};$('mkCur').onclick=function(){boxes().forEach(function(b){b.checked=+b.value<=cur;});};
  [].forEach.call(document.querySelectorAll('[data-mn]'),function(b){b.onclick=function(){var ch=boxes().filter(function(x){return x.checked;}).map(function(x){return +x.value;});
    if(!ch.length){toast('請至少選一章');return;}mockStart(ch,+b.dataset.mn);};});}
function mockPool(chs,n,only){var a=[],b=[];
  if(only){only.forEach(function(w){if(w.s!=null)b.push(schQ(w.s));else if(QUIZ[w.c]&&QUIZ[w.c][w.i])a.push(quizQ(w.c,w.i));});return a.concat(b).sort(function(){return Math.random()-0.5;}).slice(0,n);}
  chs.forEach(function(c){(QUIZ[c]||[]).forEach(function(_,i){a.push(quizQ(c,i));});SCH.forEach(function(s,k){if(s[2]===c)b.push(k);});});
  a.sort(function(){return Math.random()-0.5;});b.sort(function(){return Math.random()-0.5;});
  var nb=Math.min(b.length,Math.round(n*0.35)),out=a.slice(0,n-nb);b.slice(0,n-out.length).forEach(function(k){out.push(schQ(k));});
  return out.sort(function(){return Math.random()-0.5;});}
function mockStart(chs,n,only){var list=mockPool(chs,n,only);if(!list.length){toast('這個範圍目前沒有題目');return;}
  MK={list:list,k:0,ans:[],t0:Date.now(),chs:chs};mockShow();}
function mmss(ms){var s=Math.floor(ms/1000);return Math.floor(s/60)+':'+('0'+s%60).slice(-2);}
function mockShow(){var m=MK,x=m.list[m.k];
  openCard('<div class="who">模擬測驗・第 '+(m.k+1)+'／'+m.list.length+' 題<span id="mkT">'+mmss(Date.now()-m.t0)+'</span></div><p class="sub">第'+cnum(x.c+1)+'章 '+esc(SYL[x.c].t)+'</p><p class="dsq">'+esc(x.q)+'</p><div class="ops">'+
    x.o.map(function(o,i){return '<button class="op" data-i="'+i+'"><b>'+'ABCD'[i]+'</b>'+esc(o)+'</button>';}).join('')+'</div><div class="acts"><button class="b2" id="mkQuit">放棄測驗</button></div>','q');
  clearInterval(mockShow.h);mockShow.h=setInterval(function(){var t=$('mkT');if(t&&MK)t.textContent=mmss(Date.now()-MK.t0);else clearInterval(mockShow.h);},1000);
  [].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){b.onclick=function(){m.ans[m.k]=+b.dataset.i;b.classList.add('kb');
    setTimeout(function(){if(m.k<m.list.length-1){m.k++;mockShow();}else mockEnd();},160);};});
  $('mkQuit').onclick=function(){clearInterval(mockShow.h);MK=null;academy('mock');};}
function mockEnd(){clearInterval(mockShow.h);var m=MK,Q=SQ(),ok=0,by={},wrong=[];Q.sw=Q.sw||[];
  m.list.forEach(function(x,j){var r=m.ans[j]===x.a;if(r)ok++;var b=by[x.c]=by[x.c]||[0,0];b[1]++;if(r)b[0]++;
    var st=Q.stat[x.c]=Q.stat[x.c]||{n:0,ok:0};st.n++;if(r)st.ok++;
    if(x.i>=0){var key=x.c+':'+x.i;Q.wrong=Q.wrong.filter(function(w){return w.c+':'+w.i!==key;});if(!r)Q.wrong.unshift({c:x.c,i:x.i});}
    else{Q.sw=Q.sw.filter(function(s){return s!==x.s;});if(!r)Q.sw.unshift(x.s);}
    if(!r)wrong.push([x,m.ans[j]]);});
  Q.wrong=Q.wrong.slice(0,200);Q.sw=Q.sw.slice(0,200);var sc=Math.round(ok/m.list.length*100);Q.mock=(Q.mock||[]).concat([{d:G.day,s:sc,n:m.list.length}]).slice(-20);saveG();
  var h='<h3>模擬測驗成績</h3><p class="big">'+sc+' 分</p><p class="sub">答對 '+ok+'／'+m.list.length+' 題・用時 '+mmss(Date.now()-m.t0)+'</p><h3>各章表現</h3><p>'+
    Object.keys(by).sort(function(a,b){return a-b;}).map(function(c){var b=by[c];return '<span class="key'+(b[0]/b[1]>=0.8?' on':'')+'">第'+cnum(+c+1)+'章 '+b[0]+'／'+b[1]+'</span>';}).join('')+'</p>'+
    (wrong.length?'<h3>錯題檢討（已收進錯題本）</h3>'+wrong.map(function(w){var x=w[0];return '<div class="res bad"><b>'+esc(x.q)+'</b><p>你的答案：'+(w[1]==null?'未作答':'ABCD'[w[1]]+'. '+esc(x.o[w[1]]))+'<br>正確答案：'+'ABCD'[x.a]+'. '+esc(x.o[x.a])+'</p><p class="sub">'+esc(x.why)+'</p></div>';}).join(''):'<p class="court">全部答對，皇上學養深厚！</p>')+
    '<div class="acts"><button class="b1" id="mkAgain">同範圍再考一次</button>'+(wrong.length?'<button class="b2" id="mkWrong">只練這次的錯題</button>':'')+'<button class="b2" id="mkHome">回書院</button></div>';
  var chs=m.chs,ws=wrong.map(function(w){return w[0].i>=0?{c:w[0].c,i:w[0].i}:{s:w[0].s};});MK=null;
  openCard(h,'notes acad');$('mkAgain').onclick=function(){mockStart(chs,m.list.length);};$('mkHome').onclick=function(){academy();};
  if($('mkWrong'))$('mkWrong').onclick=function(){mockStart(chs,ws.length,ws);};}
// ---------------- 錯題本 ----------------
function acWrong(){var Q=SQ(),sw=Q.sw||[],items=Q.wrong.map(function(w){return QUIZ[w.c]&&QUIZ[w.c][w.i]?quizQ(w.c,w.i):null;}).filter(Boolean);
  var h='<p class="sub">殿試與模擬測驗答錯的題目都會收在這裡；答對一次就會移出。</p>';
  if(!items.length&&!sw.length){$('acB').innerHTML=h+'<p class="court">錯題本是空的，繼續保持！</p>';return;}
  h+='<div class="acts"><button class="b1" id="wrAll">重練全部錯題（'+(items.length+sw.length)+' 題）</button></div>'+
    items.map(function(x){return '<div class="res bad"><b>第'+cnum(x.c+1)+'章｜'+esc(x.q)+'</b><p>正確答案：'+esc(x.o[x.a])+'</p><p class="sub">'+esc(x.why)+'</p></div>';}).join('')+
    sw.map(function(k){var s=SCH[k];return s?'<div class="res bad"><b>學者題｜'+esc(s[0])+'</b><p>'+esc(s[1])+'（第'+cnum(s[2]+1)+'章）</p></div>':'';}).join('');
  $('acB').innerHTML=h;var all=Q.wrong.map(function(w){return {c:w.c,i:w.i};}).concat(sw.map(function(k){return {s:k};}));
  $('wrAll').onclick=function(){mockStart([],all.length,all);};}
// ---------------- 學者速查 ----------------
function acSch(){$('acB').innerHTML='<p class="sub">行政學最常考「誰提出什麼」。可輸入學者或理論關鍵字搜尋。</p><div class="tf"><input id="schQ" placeholder="例如：Simon、課責、預算"></div><div id="schL"></div>';
  function draw(){var q=($('schQ').value||'').trim().toLowerCase(),out='',last=-1;
    SCH.map(function(s,k){return [s,k];}).filter(function(p){return !q||(p[0][0]+p[0][1]).toLowerCase().indexOf(q)>=0;}).sort(function(a,b){return a[0][2]-b[0][2];}).forEach(function(p){var s=p[0];
      if(s[2]!==last){last=s[2];out+='<h3>第'+cnum(s[2]+1)+'章 '+esc(SYL[s[2]].t)+'</h3>';}out+='<div class="schr"><b>'+esc(s[0])+'</b><span>'+esc(s[1])+'</span></div>';});
    $('schL').innerHTML=out||'<p class="sub">找不到符合的學者或理論。</p>';}
  $('schQ').oninput=draw;draw();}
// ---------------- 入口 ----------------
function academyInit(){var _rm=royalMenu;royalMenu=function(){_rm.apply(this,arguments);var l=$('rmLog');if(!l)return;var b=document.createElement('button');b.className='b1';b.id='rmAcad';b.textContent='📚 書院（自由複習）';
    l.parentNode.insertBefore(b,l);b.onclick=function(){academy();};};
  $('bMenu').onclick=function(){royalMenu();};
  document.addEventListener('keydown',function(e){var t=e.target.tagName;if(t==='INPUT'||t==='TEXTAREA'||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='b'&&$('card').hidden){academy();e.preventDefault();}});
  if(window.__C){__C.academy=academy;__C.mockStart=mockStart;__C.SCH=SCH;}}

// ==========================================================================
// 午膳小憩與經筵講學
// 戌時（v90 延後一個時辰）：傳膳用晚膳（必做）。午時～未時（v74 提早一個時辰）：到中書省書院，由大臣講授今日小節並當堂考校。
// 尚未完成時，下午時間不加速，任務列與指標會引導皇上前往。
// ==========================================================================
var LS=null;
function lsDone(){return R0().lessonDay===G.day;}
function noonDone(){return R0().noonDay===G.day;}
function lsPhase(){var p=phase()[1];return p==='午時'||p==='未時';}   /* v74：提早一個時辰 */
function lsNear(){return Math.hypot(LOC.office[0]-PL.pos[0],LOC.office[1]-PL.pos[2])<2.6;}
function lsMark(k,name){var D=dailyState();if(!D.done[k]){D.done[k]=1;if(DAILY.some(function(g){return g[0]===k;}))toast('✅ 每日目標：'+name+'（'+dailyN(D)+'／'+DAILY.length+'）',2600);}dailyCheck();saveG();}
// ---------- 午膳小憩 ----------
function noonRest(){if(noonDone())return;var R=R0();R.noonDay=G.day;lsMark('noon','晚膳');UI.locked=true;PL.once='eat';PL.play('eat',0.2);sub(PEOPLE.eu.n,'傳膳——',1800);
  setTimeout(function(){sub(PEOPLE.eu.n,pick(['主子用過晚膳，歇一會兒吧。奴才在外頭守著。','御膳房今兒燉了羊肉湯，主子慢用。','主子用完膳，戌時還要去後宮探望白兔娘娘呢。']),2600);},1900);
  setTimeout(function(){if(typeof curtain==='function')curtain(false,'','晚膳','用罷晚膳・白兔娘娘在後宮等著皇上',2600);
    setTimeout(function(){G.hr=Math.max(G.hr,19.02);UI.locked=false;saveG();hud();},900);},7500);}   /* 坐著慢慢用膳約 7 秒再轉場 */
// ---------- 經筵 ----------
function lsTeacher(){return MIN[(G.day+1)%3];}
function lesson(){if(lsDone()||G.over)return;var ch=chIdx(),d=dIdx(),L=(BANK[ch+'-'+d]||[]).slice();
  if(!L.length){toast('今日的講義尚未備妥');return;}
  var seen={};G.notes.forEach(function(n){seen[n.title]=1;});
  L.sort(function(a,b){return (seen[a.title]?1:0)-(seen[b.title]?1:0)||Math.random()-0.5;});
  var T=lsTeacher();faceTo(T,PL.pos[0],PL.pos[2],1);
  var qs=(QUIZ[ch]||[]).map(function(_,i){return quizQ(ch,i);}).sort(function(){return Math.random()-0.5;}).slice(0,2),ks=[];
  SCH.forEach(function(s,k){if(s[2]===ch)ks.push(k);});if(ks.length)qs.push(schQ(ks[Math.floor(Math.random()*ks.length)]));
  LS={ch:ch,d:d,T:T,slides:L.slice(0,3),qs:qs,k:0,ok:0};lsSlide();}
function lsSlide(){var s=LS,P=PEOPLE[s.T.id],q=s.slides[s.k],e=q.exam||{},topic=(SYL[s.ch].d[s.d]||'').split('：')[0];
  var open=s.k===0?'<p class="court">啟奏皇上，今日經筵，'+P.self+'為陛下講「'+esc(topic)+'」。共三講，講畢當堂考校三題。</p>':'';
  openCard('<div class="who">經筵・'+esc(P.n)+'<span>第'+cnum(s.k+1)+'講／共三講</span></div>'+open+
    '<h3>'+esc(q.title)+'</h3><p class="sub">'+esc(q.ev)+'</p><div class="exam"><p>'+esc(e.core)+'</p><p class="sub">出處：'+esc(e.masters)+'</p><p>'+[].concat(e.keys||[]).map(function(k){return '<span class="key">'+esc(k)+'</span>';}).join('')+'</p>'+
    '<p><b>申論可以這樣寫：</b>'+esc(String(e.essay||'').replace(/^申論架構：/,''))+'</p></div><div class="acts"><button class="b1" id="lsN">'+(s.k<s.slides.length-1?'請講下一段':'開始考校')+'</button>'+
    (aiOn()?'<button class="b2" id="lsAsk">向講官提問</button>':'')+'</div>','notes');
  $('lsN').onclick=function(){if(s.k<s.slides.length-1){s.k++;lsSlide();}else{s.k=0;lsQuiz();}};
  if($('lsAsk'))$('lsAsk').onclick=function(){closeCard();talkTo(s.T);};}
function lsQuiz(){var s=LS,x=s.qs[s.k],P=PEOPLE[s.T.id];
  openCard('<div class="who">經筵考校・'+esc(P.n)+'<span>第'+cnum(s.k+1)+'題／共'+cnum(s.qs.length)+'題</span></div>'+(s.k===0?'<p class="court">'+P.self+'斗膽，請陛下作答。</p>':'')+
    '<p class="dsq">'+esc(x.q)+'</p><div class="ops">'+x.o.map(function(o,i){return '<button class="op" data-i="'+i+'"><b>'+'ABCD'[i]+'</b>'+esc(o)+'</button>';}).join('')+'</div>','q');
  [].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){b.onclick=function(){lsAns(+b.dataset.i);};});}
function lsAns(i){var s=LS,x=s.qs[s.k],ok=i===x.a,Q=SQ();if(ok)s.ok++;
  var st=Q.stat[x.c]=Q.stat[x.c]||{n:0,ok:0};st.n++;if(ok)st.ok++;
  if(x.i>=0){var key=x.c+':'+x.i;Q.wrong=Q.wrong.filter(function(w){return w.c+':'+w.i!==key;});if(!ok)Q.wrong.unshift({c:x.c,i:x.i});}
  else{Q.sw=(Q.sw||[]).filter(function(v){return v!==x.s;});if(!ok)Q.sw.unshift(x.s);}
  if(typeof snd==='function')snd(ok?'good':'bad');
  [].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){var j=+b.dataset.i;b.disabled=true;if(j===x.a)b.classList.add('right');else if(j===i)b.classList.add('wrong');});
  var last=s.k>=s.qs.length-1,box=document.createElement('div');
  box.innerHTML='<div class="res '+(ok?'good':'bad')+'"><b>'+(ok?'陛下聖明，答對了。':'稟陛下，正解是 '+'ABCD'[x.a]+'。')+'</b><p>'+esc(x.why)+'</p></div><div class="acts"><button class="b1" id="lsQN">'+(last?'結束經筵':'下一題')+'</button></div>';
  $('cardBody').appendChild(box);box.scrollIntoView({block:'nearest'});$('lsQN').onclick=function(){if(last)lsEnd();else{s.k++;lsQuiz();}};}
function lsEnd(){var s=LS,R=R0(),P=PEOPLE[s.T.id],n=s.qs.length,dd=s.ok===n?[0,0,2,1]:s.ok>=n-1?[0,0,1,1]:[0,0,0,0];
  R.lessonDay=G.day;R.lessonN=(R.lessonN||0)+1;if(dd[2]||dd[3])addInd(dd,1);LS=null;saveG();hud();
  var msg=s.ok===n?'陛下過目不忘，'+P.self+'佩服之至。':s.ok>=n-1?'陛下已得要領，'+P.self+'明日再為陛下補強。':'此節尚需溫習，'+P.self+'已將講義呈入書院。';
  openCard('<div class="who">經筵・'+esc(P.n)+'<span>講畢</span></div><p class="big">'+s.ok+' ／ '+n+'</p><p class="court">'+msg+'</p>'+(dd[2]||dd[3]?'<div>'+dstr(dd)+'</div>':'')+
    '<p class="sub">今天講的內容與題目，都可以在「御」→「書院」裡再複習；答錯的題目已收進錯題本。</p><div class="acts"><button class="b1" id="lsX">退朝</button><button class="b2" id="lsAc">去書院再讀</button></div>');
  $('lsX').onclick=function(){closeCard();};$('lsAc').onclick=function(){academy('lec');};lsMark('lesson','經筵聽講');}
// ---------- 十六章修畢：結業大典，之後從第一章開始第二輪複習 ----------
function gradCard(){var Q=SQ(),n=0,ok=0,R=R0(),round=Math.floor(G.day/(SYL.length*CFG.daysPerCh));Object.keys(Q.stat).forEach(function(c){n+=Q.stat[c].n;ok+=Q.stat[c].ok;});
  var weak=null,wv=2;Object.keys(Q.stat).forEach(function(c){var st=Q.stat[c];if(st.n>=5&&st.ok/st.n<wv){wv=st.ok/st.n;weak=+c;}});
  R.gradN=round;saveG();if(typeof snd==='function')snd('ach');
  openCard('<h2 class="end">盛世・十六章修畢</h2><p class="court">皇上聖明，天下大治！行政學十六章，已全數講畢，四大指標都撐住了。</p>'+
    '<p>在位 '+(G.day)+' 天、親裁政務 '+G.qTotal+' 件、選擇題作答 '+n+' 題（答對率 '+(n?Math.round(ok/n*100):0)+'%）、經筵聽講 '+(R.lessonN||0)+' 次。</p>'+
    (weak!==null?'<p class="sub">目前最需要加強：第'+cnum(weak+1)+'章 '+esc(SYL[weak].t)+'（答對率 '+Math.round(wv*100)+'%）。</p>':'')+
    '<p>接下來會從第一章開始第'+cnum(round+1)+'輪複習，會再次遇到同樣的政務，正好檢驗是否已經真正記住。建議先到書院做一次 50 題模擬測驗，檢驗整體實力。</p>'+
    '<div class="acts"><button class="b1" id="gdMock">書院 50 題模擬測驗</button><button class="b2" id="gdGo">開始第'+cnum(round+1)+'輪</button><button class="b2" onclick="restart(true)">從頭開始新朝</button></div>','end');
  $('gdMock').onclick=function(){mockStart(SYL.map(function(_,i){return i;}),50);};$('gdGo').onclick=function(){closeCard();};}
// ---------- 引導 ----------
var LSN={d:-1,a:0,b:0};
function lessonUpdate(){var on=!G.over&&(G.court==='done'||G.court==='absent');
  window.__SLOW=on&&((phase()[1]==='戌時'&&!noonDone())||(lsPhase()&&!lsDone()));
  if(!on||UI.locked)return;if(LSN.d!==G.day){LSN={d:G.day,a:0,b:0};}
  if(phase()[1]==='戌時'&&!noonDone()&&!LSN.a){LSN.a=1;sub(PEOPLE.eu.n,'主子，戌時了，晚膳已經備好。按「用晚膳」吧。',3600);}
  if(lsPhase()&&!lsDone()&&!LSN.b){LSN.b=1;sub(PEOPLE.eu.n,'主子，'+PEOPLE[lsTeacher().id].n+'已在中書省書院候駕，今日經筵要講「'+(SYL[chIdx()].d[dIdx()]||'').split('：')[0]+'」。',4200);}}
function lessonInit(){
  DAILY.push(['lesson','經筵聽講']);
  PLACES.forEach(function(p){if(p[0]==='中書省')p[0]='中書省・書院';});GOTO.forEach(function(g){if(g[0]==='中書省')g[0]='中書省・書院';});
  var _q=quest;quest=function(){var on=!G.over&&(G.court==='done'||G.court==='absent');
    if(on&&phase()[1]==='戌時'&&!noonDone())return {t:'戌時：傳膳用晚膳（按「用晚膳」）',tg:null};
    if(on&&lsPhase()&&!lsDone())return {t:'經筵：到中書省書院聽'+PEOPLE[lsTeacher().id].n.split(' ')[0]+'講學',tg:LOC.office};
    return _q.apply(this,arguments);};
  var _c=ctxBtn;ctxBtn=function(){_c.apply(this,arguments);var b=$('ctx');if(UI.locked||G.over)return;var on=G.court==='done'||G.court==='absent',near=typeof NEAR!=='undefined'?NEAR:null;
    if(on&&lsPhase()&&!lsDone()&&lsNear()){b.hidden=false;b.textContent='聽經筵講學';b.onclick=lesson;return;}
    if(on&&phase()[1]==='戌時'&&!noonDone()&&(!near||near===EU)){b.hidden=false;b.textContent='用晚膳';b.onclick=noonRest;}};
  if(G.over&&G.ind.every(function(v){return v>0;})&&G.day>=SYL.length*CFG.daysPerCh){G.over=false;saveG();setTimeout(gradCard,800);}
  var _ru=rpgUpdate;rpgUpdate=function(dt){_ru.apply(this,arguments);lessonUpdate();};
  if(window.__C){__C.lesson=lesson;__C.noonRest=noonRest;}}

// ==========================================================================
// 舒適模式（減少 3D 暈眩）與章節選擇（回到已通過的章節）
// ==========================================================================
var COMFORT={on:{fov:56,camR:5.6,camPhi:1.2,follow:0,plRun:2.6,rotK:0.6},
             off:{fov:45,camR:4.6,camPhi:1.3,follow:1,plRun:3.4,rotK:1}};
function comfortSet(on,quiet){var p=on?COMFORT.on:COMFORT.off;for(var k in p)CFG[k]=p[k];CFG.comfort=on?1:0;
  if(typeof cam!=='undefined'&&cam){cam.r=CFG.camR;cam.phi=CFG.camPhi;}faceThrone();window.__ROTK=CFG.rotK;
  try{var f=document.getElementById('cFollow');if(f)f.checked=!!CFG.follow;}catch(e){}
  saveCfg();applyCfg();if(!quiet)toast(on?'已開啟舒適模式：鏡頭拉遠、視野放寬、不自動轉向，移動較平穩':'已關閉舒適模式：鏡頭貼近、自動跟到背後',4000);}
// ---------------- 章節選擇 ----------------
function maxDay(){G.maxDay=Math.max(G.maxDay||0,G.day);return G.maxDay;}
function chapterMenu(){var md=maxDay(),span=CFG.daysPerCh,maxCh=Math.min(SYL.length-1,Math.floor(md/span)),cur=chIdx(),busy=G.court==='on'||G.over;
  var h='<h2>📖 章節選擇</h2><p class="sub">可以回到任何已經到達過的章節重新上朝、複習。回去重玩不會刪除最遠進度，隨時可以回到最新的一天；四大指標維持目前數值。</p>'+
    (busy?'<p class="court">早朝進行中，請退朝後再切換章節。</p>':'')+'<div class="lst">';
  for(var c=0;c<=maxCh;c++){var done=md>=(c+1)*span;h+='<button class="b2'+(c===cur?' on':'')+'" data-cj="'+c+'"'+(busy?' disabled':'')+'>'+
    (done?'✅ ':'▶️ ')+'第'+cnum(c+1)+'章 '+esc(SYL[c].t)+(c===cur?'（目前）':'')+'</button>';}
  h+='</div>';var locked=SYL.length-1-maxCh;if(locked>0)h+='<p class="sub">尚有 '+locked+' 章未解鎖，照進度上朝即可開啟。所有章節的講義都能在「書院」裡先讀。</p>';
  h+='<div class="acts">'+(G.day<md&&!busy?'<button class="b1" id="cjLatest">回到最新進度（第'+cnum(md+1)+'天）</button>':'')+'<button class="b2" id="cjAc">去書院讀講義</button></div>';
  openCard(h,'notes');
  [].forEach.call(document.querySelectorAll('[data-cj]'),function(b){b.onclick=function(){chapterJump(+b.dataset.cj*span,'第'+cnum(+b.dataset.cj+1)+'章 '+SYL[+b.dataset.cj].t);};});
  if($('cjLatest'))$('cjLatest').onclick=function(){chapterJump(md,'最新進度');};$('cjAc').onclick=function(){academy('lec');};}
function chapterJump(day,name){maxDay();G.day=day;G.hr=4.2;G.qToday=0;G.court='wait';G.extraLeft=CFG.extraAsk;LAST_PH=null;
  PL.pos=[0,0,0.4];saveG();hud();closeCard();UI.mode='free';faceThrone();
  if(typeof curtain==='function')curtain(true,'回到',name,'貞觀元年・第'+cnum(G.day+1)+'天・寅時',2800);toast('📖 已回到'+name+'，卯時上朝',4000);}
// ---------------- 舒適視角：面向龍椅；方位：龍椅在西、太陽東升西落 ----------------
function faceThrone(){if(CFG.comfort&&typeof cam!=='undefined'&&!window.__EYE){cam.theta=0;cam.hold=1.5;}}
function sunPath(){if(!CFG.sunPath){window.__SUNV=null;return;}if(window.__ENVK&&window.__ENVK.night>0.35&&typeof moonDir==='function'){window.__SUNV=moonDir();return;}var h=G.hr%24,u=Math.PI*Math.max(0,Math.min(1,(h-6)/12)),e=Math.max(0.07,Math.sin(u)*0.95);
  // 東＝+z（宮門方向），西＝−z（龍椅方向），南＝−x，北＝+x
  window.__SUNV=[-Math.sin(u)*Math.cos(e),Math.sin(e),Math.cos(u)*Math.cos(e)];}
function compassDraw(){var c=$('mmap');if(!c||c.hidden)return;var g=c.getContext('2d'),S=c.width,f=Math.round(S*0.085);g.save();g.font='700 '+f+'px serif';g.textBaseline='middle';
  g.fillStyle='rgba(23,17,13,.75)';g.fillRect(2,2,f*2.3,f*1.3);g.fillRect(S-f*2.3-2,S-f*1.3-2,f*2.3,f*1.3);
  g.fillStyle='#e9c66a';g.textAlign='left';g.fillText('↑西',4,2+f*0.65);g.textAlign='right';g.fillText('東↓',S-4,S-2-f*0.65);g.restore();}
function comfortInit(){
  // 第一次載入新版：把舊的預設鏡頭改為舒適模式（玩家自訂過的不動）
  if(CFG.comfort==null){var o=COMFORT.off,same=true;for(var k in o)if(k!=='rotK'&&CFG[k]!==o[k])same=false;if(same)comfortSet(true,true);else{CFG.comfort=0;saveCfg();}}
  // 舒適模式改為高視角俯瞰；畫面整體調亮（只更新仍是舊預設的玩家）
  if(CFG.comfort===1&&[6.2,7.4,8.4,8.6,10.5].indexOf(CFG.camR)>=0){comfortSet(true,true);}
  if(!CFG.bright2){if(CFG.ambK===1)CFG.ambK=1.35;if(CFG.exp===1)CFG.exp=1.1;CFG.bright2=1;saveCfg();applyCfg();}
  window.__ROTK=CFG.rotK||1;maxDay();
  var _fo=fpOff;fpOff=function(){_fo.apply(this,arguments);faceThrone();};setTimeout(faceThrone,300);
  var _mm=minimap;minimap=function(){_mm.apply(this,arguments);compassDraw();};
  var _ru2=rpgUpdate;rpgUpdate=function(dt){_ru2.apply(this,arguments);sunPath();};
  var _nd=nextDay;nextDay=function(){_nd.apply(this,arguments);maxDay();saveG();};
  var _rm=royalMenu;royalMenu=function(){_rm.apply(this,arguments);var l=$('rmLog');if(!l)return;
    var a=document.createElement('button');a.className='b2';a.id='rmChap';a.textContent='📖 章節選擇（回到已通過的章節）';a.onclick=chapterMenu;l.parentNode.insertBefore(a,l);
    var c=document.createElement('button');c.className='b2';c.id='rmComfort';c.textContent=CFG.comfort?'🩹 舒適模式：開（減少 3D 暈眩）':'🩹 舒適模式：關（點此開啟，減少 3D 暈眩）';
    c.onclick=function(){comfortSet(!CFG.comfort);royalMenu();};l.parentNode.insertBefore(c,l);};
  $('bMenu').onclick=function(){royalMenu();};
  if(window.__C){__C.chapterMenu=chapterMenu;__C.chapterJump=chapterJump;__C.comfortSet=comfortSet;}}

// ==========================================================================
// 防穿模：人物彼此推開、不穿過柱子／香爐／燈柱／書案／屏風／兵器架／木樁
// 早朝暫停：皇上可以臨時中斷早朝，有空再回來繼續
// 名牌防重疊：互相遮住的人物名牌，較遠的自動淡化
// ==========================================================================
var BODY_R=0.3,OBST=null,RAB_R=0.27,
  RAB_OBST=[{t:'b',x:0,z:-4.92,w:1.75,d:1.3}];   // 丹陛（含台階）：兔子跳不上去，視為障礙
function obstBuild(){var o=[],c=function(x,z,r){o.push({t:'c',x:x,z:z,r:r});},b=function(x,z,w,d){o.push({t:'b',x:x,z:z,w:w/2,d:d/2});};
  [-3.9,3.9].forEach(function(x){[-5.0,-2.2,0.6].forEach(function(z){c(x,z,0.36);});});   // 朱紅大柱
  [-2.2,2.2].forEach(function(x){c(x,-3.9,0.26);});                                        // 香爐
  [LOC.office,LOC.east,LOC.harem,LOC.bed].forEach(function(p){c(p[0]+0.9,p[1]-0.9,0.14);});  // 燈柱
  b(LOC.office[0],LOC.office[1]-0.2,1.2,0.6);                                              // 中書省書案
  if(!CFG.dragon)b(0,-6.4,4.3,0.16);else{b(0,-8.2,4.0,4.0);b(0,-15.5,3.4,8.0);}   // 屏風；有黑龍時改成龍身（兩翼在頭頂上方，可從下方走過）
  c(FIRE_POS[0],FIRE_POS[2],0.72);[-2.75,2.75].forEach(function(x){c(x,-4.6,0.36);});   // 營火、天子劍座                                                                      // 御座後屏風
  c(LOC.east[0]-0.6,LOC.east[1]-1.0,0.08);c(LOC.east[0]+0.6,LOC.east[1]-1.0,0.08);           // 兵器架
  c(LOC.east[0]+1.2,LOC.east[1]+0.4,0.16);                                                 // 練武木樁
  return o;}
function pushOut(a,o){var p=a.pos,r=BODY_R;
  if(o.t==='c'){var dx=p[0]-o.x,dz=p[2]-o.z,d=Math.hypot(dx,dz),m=o.r+r;if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}p[0]=o.x+dx/d*m;p[2]=o.z+dz/d*m;}}
  else{var cx=Math.max(o.x-o.w,Math.min(o.x+o.w,p[0])),cz=Math.max(o.z-o.d,Math.min(o.z+o.d,p[2])),ex=p[0]-cx,ez=p[2]-cz,e=Math.hypot(ex,ez);
    if(e<r){if(e<1e-4){var l=p[0]-(o.x-o.w),rr=(o.x+o.w)-p[0],t=p[2]-(o.z-o.d),bt=(o.z+o.d)-p[2],mn=Math.min(l,rr,t,bt);
        if(mn===l)p[0]=o.x-o.w-r;else if(mn===rr)p[0]=o.x+o.w+r;else if(mn===t)p[2]=o.z-o.d-r;else p[2]=o.z+o.d+r;}
      else{p[0]=cx+ex/e*r;p[2]=cz+ez/e*r;}}}}
function bodies(){var L=[PL,EU,PR].concat(MIN);return L.filter(function(a){return a&&a.pos&&!a.hidden&&!(a===PR&&PR.flight);});}
function collide(){if(!CFG.collide||G.over)return;if(UI.mode==='court'&&G.court==='on')return; // 早朝就位時不推動
  if(!OBST)OBST=obstBuild();var B=bodies(),i,j;
  for(i=0;i<B.length;i++)for(j=i+1;j<B.length;j++){var a=B[i],b=B[j],dx=b.pos[0]-a.pos[0],dz=b.pos[2]-a.pos[2],d=Math.hypot(dx,dz),m=BODY_R*2;
    if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}var k=(m-d)/2,ux=dx/d,uz=dz/d,wa=a===EU?1:b===EU?0:a===PL?0.35:0.5,wb=b===EU?1:a===EU?0:b===PL?0.35:0.5;   // 太監一律讓開   // 皇上比較「重」，主要由 NPC 讓開
      a.pos[0]-=ux*k*2*wa;a.pos[2]-=uz*k*2*wa;b.pos[0]+=ux*k*2*wb;b.pos[2]+=uz*k*2*wb;}}
  B.forEach(function(a){if(a.y>DAIS*0.5&&onDais(a.pos[0],a.pos[2]))return;OBST.forEach(function(o){pushOut(a,o);});});
  if(typeof hero!=='undefined'&&hero&&hero.pos){var rb={pos:hero.pos};B.forEach(function(a){var dx=hero.pos[0]-a.pos[0],dz=hero.pos[2]-a.pos[2],d=Math.hypot(dx,dz),m=(a===PL&&typeof RAB!=='undefined'&&RAB.fav)?0.36:BODY_R+RAB_R;
    if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}hero.pos[0]=a.pos[0]+dx/d*m;hero.pos[2]=a.pos[2]+dz/d*m;}});var r0=BODY_R;BODY_R=RAB_R;OBST.concat(RAB_OBST).forEach(function(o){pushOut(rb,o);});
    if(typeof RAB!=='undefined'&&RAB.tg){if(Math.abs(RAB.tg[0])<2.2&&RAB.tg[1]<-3.4&&RAB.tg[1]>-6.3)RAB.tg[1]=-3.4-Math.random()*0.8;   // 想去丹陛上就改到台階前
      var tg={pos:[RAB.tg[0],0,RAB.tg[1]]};BODY_R=RAB_R+0.15;OBST.concat(RAB_OBST).forEach(function(o){pushOut(tg,o);});RAB.tg[0]=tg.pos[0];RAB.tg[1]=tg.pos[2];}BODY_R=r0;}}
// ---------------- 名牌防重疊 ----------------
function lblDeclutter(){var L=[].slice.call(document.querySelectorAll('#lbls .lbl')).filter(function(e){return e.style.display!=='none'&&e.offsetParent!==null;});
  var R=L.map(function(e){return e.getBoundingClientRect();}),hide=[];
  for(var i=0;i<L.length;i++){if(L[i].classList.contains('place'))continue;for(var j=0;j<L.length;j++){if(i===j||hide[i])continue;var a=R[i],b=R[j];
    if(a.left<b.right-4&&b.left<a.right-4&&a.top<b.bottom-2&&b.top<a.bottom-2){if(a.top<b.top||(a.top===b.top&&i>j))hide[i]=1;}}}
  L.forEach(function(e,i){e.style.opacity=hide[i]?'0.18':'';});}
// ---------------- 早朝暫停 ----------------
function courtPauseAsk(){openCard('<div class="who">暫停早朝<span>金鑾殿</span></div><p class="court">皇上要暫時退入後殿嗎？</p>'+
  '<p>百官會在金鑾殿原地候旨，已經處理的奏摺都會保留。皇上可以先四處走走，有空時按畫面上的「繼續早朝」，或走回金鑾殿，就能接著議事。</p>'+
  '<p class="sub">早朝暫停期間，午膳、經筵等下朝後的行程會順延；若到就寢都沒回來，今天剩下的奏摺就視同未奏。</p>'+
  '<div class="acts"><button class="b1" id="cpGo">繼續議事</button><button class="b2" id="cpPause">暫停，稍後再議</button></div>','q');
  $('cpGo').onclick=function(){courtNext();};$('cpPause').onclick=courtPause;}
