  var P=TR.p,u=P.u;gl.useProgram(P.p);common(P,sunW,shadowVP);gl.uniformMatrix4fv(u.uVP,false,vp);gl.uniform3fv(u.uCam,eye);gl.uniform1f(u.uT,(performance.now()-TR.t0)/1000);gl.uniform1f(u.uNight,(window.__ENVK&&window.__ENVK.night)||0);
