// 武器的世界座標（依狀態：架上、皇上手中、地上、太監手中）
function basis(o,X,Y){var Z=[X[1]*Y[2]-X[2]*Y[1],X[2]*Y[0]-X[0]*Y[2],X[0]*Y[1]-X[1]*Y[0]];return new Float32Array([X[0],X[1],X[2],0,Y[0],Y[1],Y[2],0,Z[0],Z[1],Z[2],0,o[0],o[1],o[2],1]);}
function nrm(v){var l=Math.hypot(v[0],v[1],v[2])||1;return [v[0]/l,v[1]/l,v[2]/l];}
function wpnWorld(w){var st=w===WS.w?WS.state:'rack';
  if(st==='rack'){var p=slotPos(w.slot),c=Math.cos(RACK.yaw),n=Math.sin(RACK.yaw);if(w.kind==='bow')return basis([p[0]+n*0.12,p[1]+0.02,p[2]+c*0.12],[0,1,0],[-c,0,n]);if(w.kind==='staff')return basis([p[0]+n*0.06-c*0.25,p[1]+0.035,p[2]+c*0.06+n*0.25],[0,1,0],[-c,0,n]);   /* 弓：橫掛在架上，弦朝外 */
    return basis([p[0]+n*0.06-c*0.42,p[1]+0.035,p[2]+c*0.06+n*0.42],[0,1,0],[-c,0,n]);}   // 橫放在架位上
  if(st==='held'){if(w.kind==='bow'&&!(ACTN&&ACTN.m==='T'))return BW.M||null;if(!WS.grip)return null;return basis(WS.grip,WS.X,[-WS.dir[0],-WS.dir[1],-WS.dir[2]]);}
  if(st==='fly'){var F=WS.fly;return basis(F.p,F.X,[-F.d[0],-F.d[1],-F.d[2]]);}
  if(st==='ground'){var g=WS.gp,cy=Math.cos(WS.gyaw),sy=Math.sin(WS.gyaw);return basis([g[0],g[1]+(w.kind==='bow'?0.11:0.05),g[2]],[cy,0,-sy],[sy,0,cy]);}
  if(st==='carry'){var E=EU,ey=E.yaw,s2=Math.sin(ey),c2=Math.cos(ey);return basis([E.pos[0]+s2*0.35,(E.y||0)+1.0,E.pos[2]+c2*0.35],[0,1,0],[c2,0,-s2]);}   // 太監雙手橫捧
  return null;}
// ---------- 向量／四元數小工具 ----------
function v_s(a,b){return [a[0]-b[0],a[1]-b[1],a[2]-b[2]];}function v_a(a,b,k){return [a[0]+b[0]*k,a[1]+b[1]*k,a[2]+b[2]*k];}
function v_d(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}function v_c(a,b){return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}function v_l(a){return Math.hypot(a[0],a[1],a[2]);}
function acs(x){return Math.acos(Math.max(-1,Math.min(1,x)));}
function q_m(a,b){return [a[3]*b[0]+a[0]*b[3]+a[1]*b[2]-a[2]*b[1],a[3]*b[1]-a[0]*b[2]+a[1]*b[3]+a[2]*b[0],a[3]*b[2]+a[0]*b[1]-a[1]*b[0]+a[2]*b[3],a[3]*b[3]-a[0]*b[0]-a[1]*b[1]-a[2]*b[2]];}
function q_i(q){return [-q[0],-q[1],-q[2],q[3]];}function q_ax(ax,an){var s=Math.sin(an/2);return [ax[0]*s,ax[1]*s,ax[2]*s,Math.cos(an/2)];}
function q_n(q){var l=Math.hypot(q[0],q[1],q[2],q[3])||1;return [q[0]/l,q[1]/l,q[2]/l,q[3]/l];}
function q_r(q,v){var p=q_m(q_m(q,[v[0],v[1],v[2],0]),q_i(q));return [p[0],p[1],p[2]];}
function q_of(M){var c0=nrm([M[0],M[1],M[2]]),c1=nrm([M[4],M[5],M[6]]),c2=nrm([M[8],M[9],M[10]]),m00=c0[0],m10=c0[1],m20=c0[2],m01=c1[0],m11=c1[1],m21=c1[2],m02=c2[0],m12=c2[1],m22=c2[2],t=m00+m11+m22,s;
  if(t>0){s=Math.sqrt(t+1)*2;return q_n([(m21-m12)/s,(m02-m20)/s,(m10-m01)/s,0.25*s]);}
  if(m00>m11&&m00>m22){s=Math.sqrt(1+m00-m11-m22)*2;return q_n([0.25*s,(m01+m10)/s,(m02+m20)/s,(m21-m12)/s]);}
  if(m11>m22){s=Math.sqrt(1+m11-m00-m22)*2;return q_n([(m01+m10)/s,0.25*s,(m12+m21)/s,(m02-m20)/s]);}
  s=Math.sqrt(1+m22-m00-m11)*2;return q_n([(m02+m20)/s,(m12+m21)/s,0.25*s,(m10-m01)/s]);}
