 1:{dur:0.40,hit:0.42,lock:0.52,step:0.3,sway:[0.22,-0.2],k:[[0.30,[0.1,0.25,0.55],[-0.15,0.8,0.45]],[0.52,[0.7,-0.35,-0.25],[0.55,-0.5,-0.65]]]},           // 一式：斜劈（左上 → 右下）
 2:{dur:0.38,hit:0.40,lock:0.50,step:0.25,sway:[-0.22,0.28],k:[[0.25,[0.45,0.0,-0.5],[0.25,0.05,-0.97]],[0.38,[0.8,0.02,0.05],[1,0.05,0]],[0.50,[0.45,0.05,0.65],[-0.15,0.05,1]]]},   // 二式：反手橫斬（右 → 左）
 3:{dur:0.58,hit:0.50,lock:0.56,step:0.7,sway:[0.05,0],bow:0.3,k:[[0.32,[0.05,0.62,0.3],[-0.45,0.85,0.15]],[0.42,[0.5,0.5,0.15],[0.9,0.4,0]],[0.55,[0.75,-0.3,0.12],[0.55,-0.83,0]]]},   // 三式：躍步豎劈（收招）
