function ease(x){return x*x*(3-2*x);}
function lerp3(a,b,k){return [a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k,a[2]+(b[2]-a[2])*k];}
// 依時間取出目前的手位與劍向（key[0] 用起招時的實際姿勢，招與招之間不會跳）
function movEval(M,k0,x){var K=[[0,k0.h,k0.d]].concat(M.k).concat([[1,POSE_IDLE.h,POSE_IDLE.d]]);for(var i=0;i<K.length-1;i++){if(x<=K[i+1][0]){var e=ease((x-K[i][0])/Math.max(1e-4,K[i+1][0]-K[i][0]));return {h:lerp3(K[i][1],K[i+1][1],e),d:nrm(lerp3(K[i][2],K[i+1][2],e))};}}return {h:POSE_IDLE.h,d:nrm(POSE_IDLE.d)};}
