function aimYaw(){if(pin&&pin.mag>0.15)return Math.atan2(pin.x,pin.z);var best=null,bd=2.8,cand=NPC.map(function(a){return [a.pos[0],a.pos[2]];}).concat([[LOC.east[0]+1.2,LOC.east[1]+0.4]]);
  cand.forEach(function(p){var dx=p[0]-PL.pos[0],dz=p[1]-PL.pos[2],d=Math.hypot(dx,dz),a=Math.atan2(dx,dz),da=Math.abs(Math.atan2(Math.sin(a-PL.yaw),Math.cos(a-PL.yaw)));if(d<bd&&da<1.9){bd=d;best=a;}});return best;}
