// 依日期洗牌（同一天固定、每天不同）
function dRand(seed){var s=seed*9301+49297;return function(){s=(s*9301+49297)%233280;return s/233280;};}
function dineMenu(){var sc=dineScore(),tier=sc.s>=5?3:sc.s>=3.2?2:sc.s>=1.6?1:0,n=Math.max(2,Math.min(6,2+Math.floor(sc.s*0.8))),why=[];
  if(sc.fisc<30&&tier>0){tier--;why.push('國庫吃緊，御膳房減了一等');}
  var rnd=dRand(G.day*7+tier+3),sh=function(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(rnd()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;},ate=dishBook();
  var top=sh(DISHES[tier]).sort(function(a,b){return (ate[a[0]]?1:0)-(ate[b[0]]?1:0);}),pool=top.slice(0,n).map(function(d){return d.concat([tier]);});   /* 優先上沒吃過的菜 */
  if(tier>0&&n>=3){var side=sh(DISHES[tier-1])[0];pool[n-1]=side.concat([tier-1]);}   /* 搭一道下一等的小菜 */
  var L=pool.map(function(p,i){return {name:p[0],kind:p[1],c1:p[2],c2:p[3],desc:p[4],tier:p[5],served:false,eaten:false,slot:i};});
  return {day:G.day,tier:tier,dishes:L,score:sc,why:why};}
function dishBook(){var R=R0();if(!R.book)R.book={};return R.book;}
function dishInit(){var _e=eatUpdate;eatUpdate=function(dt){var d=DM.eating,r=_e.apply(this,arguments);
    if(d&&d.eaten&&!d.booked){d.booked=1;var B=dishBook(),nw=!B[d.name];B[d.name]=G.day+1;var n=Object.keys(B).length;if(nw)setTimeout(function(){toast('📖 御膳譜新收錄「'+d.name+'」・已嚐 '+n+'／'+DISH_TOTAL+' 道',2600);if(typeof smp==='function')smp('success',0.35);},3100);saveG();}return r;};}

