// ---------- 角色風格：每個人都有自己的走路、跑步與動作風格 ----------
var MC_ROLE={eu:'not-confident',pr:'active',m0:'masculinity',m1:'normal',m2:'angry'};
function mcStyleOf(a){if(a===PL){var ind=G.ind||[50,50,50,50],avg=(ind[0]+ind[1]+ind[2]+ind[3])/4;return avg>=68?'masculinity':avg>=50?'normal':avg>=35?'tired':'old';}return MC_ROLE[a.id]||'normal';}
function mcKey(content,style){var k=content+'|'+style;if(MOCAP[k])return k;k=content+'|normal';if(MOCAP[k])return k;for(var x in MOCAP)if(x.indexOf(content+'|')===0)return x;return null;}
// 播一段動作（一次性）；回傳是否成功
function mcPlay(a,content,style,fade){if(!a)return false;var k=mcKey(content,style||mcStyleOf(a));if(!k)return false;
  if(a.kind==='war'){var nm=mcWarClip(k);if(!nm)return false;a.play(nm,fade||0.25);return true;}
  var rk=a===PL?'asura':a===EU?'drake':a===PR?'corps':null;if(!rk||!a.A)return false;var nm2=mcAdd(a,rk,k);if(!nm2)return false;a.once=nm2;a.play(nm2,fade||0.25);return true;}
// 把角色的走路／跑步換成有風格的真人動作（並依動作的實際步速調整播放速度，避免滑步）
function mcLocoKey(c,st){var L=[c+'|'+st,c+'|'+st+'|2',c+'|'+st+'|b',c+'|normal',c+'|normal|2',c+'|normal|b'];for(var i=0;i<L.length;i++)if(MOCAP[L[i]]&&MOCAP[L[i]].lp)return L[i];for(var x in MOCAP)if(x.indexOf(c+'|')===0&&MOCAP[x].lp)return x;return mcKey(c,st);}
function mcLoco(a,walkStyle,runStyle){if(!a)return;var wk=mcLocoKey(a===PR?'run':'walk',walkStyle),rk=mcLocoKey(a===PR?'dash':'run',runStyle||walkStyle);
  if(a.kind==='war'){var w=mcWarClip(wk);if(w){a.walkClip=w;a.mcNat=MOCAP[wk].sp*1.62*a.h/1.8;}return;}
  var key=a===PL?'asura':a===EU?'drake':a===PR?'corps':null;if(!key)return;var rig=mcRig(a.A,key),s=a.scale(),wn=mcAdd(a,key,wk),rn=mcAdd(a,key,rk);
  if(wn){a.walkClip=wn;a.natW=MOCAP[wk].sp*rig.leg*s;}if(rn&&a!==PL){a.runClip=rn;a.natR=MOCAP[rk].sp*rig.leg*s;}}
// 皇上：依國勢心情換走路風格；拉弓／施法時用真人的左右橫走、後退
function mcPL(c){var st=window.__STRAFE!=null,k=null;
  if(st&&(PL.vs||0)>0.08){var ty=Math.atan2(pin.x,pin.z),dy=Math.atan2(Math.sin(ty-PL.yaw),Math.cos(ty-PL.yaw)),ad=Math.abs(dy);k=mcLocoKey(ad<0.7?'walk':ad>2.4?'walk-back':dy>0?'walk-left':'walk-right','normal');}
  else if(c==='walk'){var sty=mcStyleOf(PL);if(sty!=='normal'){k=mcLocoKey('walk',sty);if(k==='walk|normal')k=null;}}
  if(!k){PL.walkClip='walk';return c;}var nm=mcAdd(PL,'asura',k);if(!nm){PL.walkClip='walk';return c;}PL.walkClip=nm;PL.natW=MOCAP[k].sp*mcRig(PL.A,'asura').leg*PL.scale();return nm;}
// 動作庫：皇上可以在「御」選單裡把 242 段真人動作挑給任何人做
function mcLibrary(){var who=MC.who||0,grp={},order=[];Object.keys(MOCAP).forEach(function(k){var p=k.split('|');if(!grp[p[0]]){grp[p[0]]=[];order.push(p[0]);}grp[p[0]].push(k);});
  var W=['皇上','總管太監','太子','三位大臣','全體'],h='<h2>🎞️ 動作庫</h2><p class="sub">共 '+Object.keys(MOCAP).length+' 段真人動作捕捉，'+order.length+' 類，每類多種情緒風格。點一下就由選定的人當場演出。</p>'+
    '<div class="grid">'+W.map(function(w,i){return '<button class="'+(i===who?'b1':'b2')+'" data-mw="'+i+'">'+w+'</button>';}).join('')+'</div>';
  order.forEach(function(c){h+='<h3>'+(MC_CONTENT_ZH[c]||c)+'（'+grp[c].length+'）</h3><div class="grid">'+grp[c].map(function(k){var p=k.split('|');return '<button class="b2" data-mk="'+k+'">'+(MC_STYLE_ZH[p[1]]||p[1])+(p[2]?(p[2]==='2'?'・二':'・乙'):'')+'</button>';}).join('')+'</div>';});
  h+='<p class="sub" style="margin-top:12px;opacity:.75">'+MC.cr+'。僅供非商業學習使用。</p>';openCard(h,'notes');
  [].forEach.call(document.querySelectorAll('#cardBody [data-mw]'),function(b){b.onclick=function(){MC.who=+b.dataset.mw;mcLibrary();};});
  [].forEach.call(document.querySelectorAll('#cardBody [data-mk]'),function(b){b.onclick=function(){var k=b.dataset.mk,p=k.split('|'),L=[[PL],[EU],[PR],MIN,[PL,EU,PR].concat(MIN)][MC.who||0];closeCard();
    L.forEach(function(a,i){setTimeout(function(){mcPlayKey(a,k);},i*120);});toast('演示：'+(MC_CONTENT_ZH[p[0]]||p[0])+'・'+(MC_STYLE_ZH[p[1]]||p[1]),1600);};});}
function mcPlayKey(a,k){if(!a||a.hidden)return;if(a.kind==='war'){var n=mcWarClip(k);if(n)a.play(n,0.25);return;}var rk=a===PL?'asura':a===EU?'drake':a===PR?'corps':null;if(!rk)return;var nm=mcAdd(a,rk,k);if(!nm)return;a.speed=0;a.once=nm;a.play(nm,0.25);a.t=0;}
function mcIdle(a){return a&&!a.hidden&&!a.once&&(a.speed||0)<0.08&&(a.kind!=='war'||a.clip==='idle');}
function mocapInit(){if(typeof MOCAP==='undefined')return;
  var _sc=sampleClip;sampleClip=function(A,name,t,T,R,S){var an=A.anims[name];if(an&&an.mc){_sc(A,'idle',t,T,R,S);mcApply(A,an,t,T,R);return;}return _sc.apply(this,arguments);};
  // 大臣：真人走路的播放速度配合實際移動速度
  var _wu=WActor.prototype.update;WActor.prototype.update=function(dt){if(this.mcNat&&this.clip===this.walkClip&&this.speed>0.05){var k=Math.max(0.6,Math.min(1.6,this.speed/this.mcNat));this.t+=dt*(k-1);}return _wu.call(this,dt);};
  mcLoco(EU,'old');mcLoco(PR,'active');MIN.forEach(function(m){mcLoco(m,MC_ROLE[m.id]||'normal');});
  /* 皇上走路維持原本的 Mixamo 動作（六臂角色套真人步態會駝背變形） */
  if(typeof isLoco==='function'){var _il=isLoco;isLoco=function(c){return _il(c)||(typeof c==='string'&&c.indexOf('mc:walk')===0);};}
  // 上朝、退朝：百官與總管太監真人鞠躬（各有各的風格）
  if(typeof bowAll==='function'){var _ba=bowAll;bowAll=function(a,ms){_ba.apply(this,arguments);if(a>0.3){MIN.concat([EU]).forEach(function(m,i){setTimeout(function(){if(mcPlay(m,'bow'))m.bow=a*0.25;},120+i*160);});}};}
  // 說話時的手勢：應答、指引、呼喚、揮手
  if(typeof soulSay==='function'){var _ss=soulSay;soulSay=function(a,t,ms){var r=_ss.apply(this,arguments);if(a&&a!==PL&&mcIdle(a)&&Math.random()<0.45){var s=String(t||''),c=/臣遵旨|遵命|是，|奴才這就|明白/.test(s)?'respond':/請|這邊|那邊|往/.test(s)?'guide':/皇上！|陛下！|主子！|來人/.test(s)?'call':/告退|退下|再會/.test(s)?'bye':pick(['respond','guide','respond','call']);if(G.court==='on'&&c!=='respond')c='respond';mcPlay(a,c);}return r;};}
  // 喝采：大臣高舉雙手／揮手，太子跳一段舞
  if(typeof everyone==='function'){var _ev=everyone;everyone=function(c,ms){if(c==='cheer'){MIN.forEach(function(m){if(mcIdle(m)&&Math.random()<0.5)setTimeout(function(){mcPlay(m,pick(['raise-up-both-hands','wave-both-hands','raise-up-right-hand']));},200+Math.random()*500);});
      if(mcIdle(PR)&&Math.random()<0.6)setTimeout(function(){mcPlay(PR,'dance-short','normal');},400);}return _ev.apply(this,arguments);};}
  // 太子練武：招式之間穿插真人的出拳、踢腿、劈砍
  if(typeof prTrain==='function'){var _pt=prTrain;prTrain=function(dt){var q0=PR.q,r=_pt.apply(this,arguments);if(PR.q&&PR.q!==q0&&PR.q.length&&Math.random()<0.45){var k=mcKey(pick(['punch','kick','slash']),'normal'),nm=k&&mcAdd(PR,'corps',k);if(nm)PR.q.splice(Math.floor(Math.random()*(PR.q.length+1)),0,nm);}return r;};}
  // 召見：被召見的人走到皇上面前先行禮
  if(typeof summon==='function'){var _sm=summon;summon=function(a){var r=_sm.apply(this,arguments);if(a&&a!==hero){var t0=performance.now(),iv=setInterval(function(){if(performance.now()-t0>20000){clearInterval(iv);return;}if(Math.hypot(a.pos[0]-PL.pos[0],a.pos[2]-PL.pos[2])<2.2&&(a.speed||0)<0.08){clearInterval(iv);mcPlay(a,'bow');}},300);}return r;};}
  // 皇上閒置：偶爾伸展、揮手（與揮棒交替）
  setInterval(function(){if(!PL||UI.locked||G.court==='on'||UI.mode!=='free'||!mcIdle(PL)||PL.clip!=='idle'||(WS&&WS.state==='held'))return;if(Math.random()<0.05)mcPlay(PL,pick(['raise-up-both-hands','wave-right-hand','raise-up-left-hand']),'normal');},1000);
  if(typeof royalMenu==='function'){var _rm=royalMenu;royalMenu=function(){_rm.apply(this,arguments);var l=$('rmHelp');if(!l||$('rmMoc'))return;var b=document.createElement('button');b.className='b2';b.id='rmMoc';b.textContent='🎞️ 動作庫';b.onclick=mcLibrary;l.parentNode.appendChild(b);};}
  if(typeof help==='function'){var _hp=help;help=function(){var r=_hp.apply(this,arguments);var cb=$('cardBody');if(cb&&!$('mcCr')){var d=document.createElement('p');d.id='mcCr';d.className='sub';d.style.opacity='.75';d.textContent=MC.cr;cb.appendChild(d);}return r;};}
  if(window.__C){__C.mcPlay=mcPlay;__C.mcPlayKey=mcPlayKey;__C.MC=MC;__C.mcLibrary=mcLibrary;__C.mcRig=mcRig;__C.PL=PL;__C.PR=PR;__C.EU=EU;__C.MIN=MIN;__C.MOCAP=MOCAP;__C.DISH_TOTAL=DISH_TOTAL;__C.mcDecode=mcDecode;__C.mcFrame=mcFrame;__C.T={say:function(a,t,m){soulSay(a,t,m);},bowAll:function(a,m){bowAll(a,m);},everyone:function(c){everyone(c);},menu:function(){royalMenu();}};}}

// ==========================================================================
// 質感升級第二輪：真實取樣音效、技能粒子特效、角色輪廓光、畫面暗角、按鍵冷卻與按壓回饋
//  ・音效取樣：Code Monkey〈Kitchen Chaos〉課程素材（腳步、刀砍、物品落地／拾起、成功／失敗、油煎、警示）
//  ・粒子：位移揚塵與風切、跳躍落地塵圈、飛刀拖尾與命中火花、兵器落地塵土、奔跑腳下塵土、箭矢拖尾
// ==========================================================================
var SB={buf:{},ld:false,loop:null},PT=[],FS2={ph:{},prevJ:false,prevD:null,prevWS:null,kn:new WeakMap(),served:0,eatT:0};
var SB_GRP={chop:3,fail:2,success:2,step:4,drop:3,pick:3,trash:2,warn:2};
function sbLoad(){var a=FX.ac;if(SB.ld||!a||a.state!=='running'||typeof SFXB==='undefined')return;SB.ld=true;
  Object.keys(SFXB).forEach(function(k){var s=atob(SFXB[k]),u=new Uint8Array(s.length);for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i);
    try{a.decodeAudioData(u.buffer,function(b){SB.buf[k]=b;},function(){});}catch(e){}});}
// 播放一段取樣：name 可以是群組名（隨機挑一個變化版），v 音量，r 播放速度（音高）
function smp(name,v,r){var a=FX.ac;if(!CFG.sfx||!a||a.state!=='running')return;sbLoad();var k=SB_GRP[name]?name+(1+Math.floor(Math.random()*SB_GRP[name])):name,b=SB.buf[k];if(!b)return;
  var s=a.createBufferSource(),g=a.createGain();s.buffer=b;s.playbackRate.value=(r||1)*(0.94+Math.random()*0.12);g.gain.value=v==null?0.4:v;s.connect(g);g.connect(FX.out);s.start();return s;}
// ---------------- 粒子 ----------------
// kind 0＝揚塵（一般混色）、1＝火花（加亮）、2＝塵圈
function puff(p,v,o){o=o||{};PT.push({p:p.slice(),v:v||[0,0,0],t:0,life:o.life||0.7,s:o.s||0.25,gr:o.gr==null?1.4:o.gr,c:o.c||[0.62,0.55,0.45],a:o.a==null?0.45:o.a,k:o.k||0,g:o.g||0,dr:o.dr==null?2.5:o.dr});if(PT.length>500)PT.splice(0,PT.length-500);}
function dustBurst(p,n,sp,o){for(var i=0;i<n;i++){var a=Math.random()*6.283,r=sp*(0.4+Math.random()*0.6);puff([p[0]+Math.cos(a)*0.1,p[1]+0.05,p[2]+Math.sin(a)*0.1],[Math.cos(a)*r,0.25+Math.random()*0.5,Math.sin(a)*r],o);}}
function sparks(p,n,c){for(var i=0;i<n;i++){var a=Math.random()*6.283,e=Math.random()*1.2,r=2+Math.random()*3;puff(p,[Math.cos(a)*Math.cos(e)*r,Math.sin(e)*r+1,Math.sin(a)*Math.cos(e)*r],{k:1,s:0.05+Math.random()*0.04,gr:-0.6,life:0.28+Math.random()*0.25,c:c||[1,0.78,0.4],a:1,g:9,dr:1});}}
function ptUpdate(dt){for(var i=PT.length-1;i>=0;i--){var q=PT[i];q.t+=dt;if(q.t>=q.life){PT.splice(i,1);continue;}var k=Math.exp(-q.dr*dt);q.v[0]*=k;q.v[2]*=k;q.v[1]=q.v[1]*k-q.g*dt;
  q.p[0]+=q.v[0]*dt;q.p[1]+=q.v[1]*dt;q.p[2]+=q.v[2]*dt;if(q.k===1&&q.p[1]<0.02){q.p[1]=0.02;q.v[1]*=-0.3;}}}
var VS_PT=`#version 300 es
in vec4 aPos;in vec4 aNor;in vec4 aUV;uniform mat4 uVP;uniform float uK;out vec4 vC;out vec2 vK;
void main(){vec4 c=uVP*vec4(aPos.xyz,1.);gl_Position=c;gl_PointSize=clamp(aPos.w*uK/max(c.w,.1),1.,300.);vC=aNor;vK=aUV.xy;}`;
var FS_PT=`#version 300 es
precision highp float;in vec4 vC;in vec2 vK;out vec4 o;
void main(){vec2 p=gl_PointCoord-.5;float r=length(p)*2.;if(r>1.)discard;
  if(vK.x<.5){float n=.75+.25*sin(p.x*17.+vK.y*40.)*sin(p.y*13.-vK.y*31.);float a=smoothstep(1.,.15,r)*vC.a*n;o=vec4(vC.rgb*a,a);}
  else if(vK.x<1.5){float a=pow(smoothstep(1.,0.,r),2.)*vC.a;o=vec4(vC.rgb*a*1.8,0.);}
  else{float a=smoothstep(.22,0.,abs(r-.78))*vC.a;o=vec4(vC.rgb*a,a*.6);}}`;
