  var dz=DINE.table;path([[1.2,1.9],[1.9,3.6],[2.0,5.2],[Math.min(DINE.seat.p[0]+0.9,2.2),DINE.seat.p[1]-0.6]],0.62);path([[DINE.seat.p[0]+1.1,DINE.seat.p[1]],[DINE.kitchen[0]-0.6,DINE.kitchen[1]]],0.62);
  // 大樹（四個角落）
  [[-7.9,-4.9,'CommonTree_1'],[7.6,5.2,'CommonTree_2'],[-6.2,7.4,'CommonTree_3'],[2.6,-8.9,'CommonTree_1'],[-8.6,1.0,'CommonTree_3']].forEach(function(q){var s=q[2]==='TwistedTree_1'?0.42:0.85;add(q[2],q[0],q[1],s);SCN.obst.push({t:'c',x:q[0],z:q[1],r:0.35});});
