// 拿掉下襬（褲裝）：下襬的布料（robe2）與下襬邊（靠近腳踝的緣飾）
function humNoSkirt(TR,R,pos){var keep=[],sk=function(v){var m=R.m[v];return m===10||(m===2&&pos[v*3+1]<-0.55&&Math.abs(pos[v*3])<0.4);};
  for(var i=0;i<TR.length;i+=3){var a=TR[i],b=TR[i+1],c=TR[i+2];if(a<R.nv&&b<R.nv&&c<R.nv&&sk(a)&&sk(b)&&sk(c))continue;keep.push(a,b,c);}return keep;}
