// ==========================================================================
// 捏臉・建立角色（登入頁）：皇上、總管太監、太子都能調體型、臉型、服色、冠帽；
// 調整時即時重建模型，角色站在紅毯前讓鏡頭繞著看；可隨機、重設、存檔，也能匯出／匯入「設定碼」。
// ==========================================================================
var CE={role:'pl',P:null,on:false,tm:0,tab:'body'};
var CE_ROLES=[['pl','皇上']];
var CE_BODY=[['g','性別','女','男',0,1],['age','年紀','年輕','年長',0,1],['mus','肌肉','纖細','壯碩',-1.6,1.6],['wt','胖瘦','清瘦','豐腴',-1.6,1.6],['h','身高','矮','高',1.1,2.4]];
var CE_FACE=[['headw','臉寬'],['headround','臉型（方↔圓）'],['eyes','眼睛大小'],['nose','鼻翼寬'],['noseL','鼻樑長'],['mouth','嘴寬'],['chin','下巴寬'],['jaw','下巴突出'],['cheek','顴骨'],['ears','耳朵'],['brow','眉角']];
