  var V=[],N=[],C=[],I=[],chunks=[],flush=function(){if(!V.length)return;chunks.push({pos:new Float32Array(V),nor:new Int8Array(N),col:new Uint8Array(C),idx:new Uint16Array(I)});V=[];N=[];C=[];I=[];};
