    L.map(function(it){var o=own[it.id];return '<div class="shIt">'+(typeof thumbH==='function'?thumbH(it.id,it):'')+'<b>'+esc(it.n)+'</b><small>'+SLOTN[it.slot]+'</small>'+(o?'<button class="b2" disabled>已擁有</button>':'<button class="b2" data-try="'+it.id+'">👁 試穿</button><button class="b1" data-buy="'+it.id+'">🪙 '+it.p+'</button>')+'</div>';}).join('')+'</div>'+
    '<p class="sub">買下的東西到「龍床旁的換裝區」穿戴。部分服飾為 CC-BY 授權，作者列在換裝區最下方。</p>';
