if(typeof DEVSPEC!=='undefined')DEVSPEC.push(['開發者特權',[['devGold','無限金幣（1 開／0 關）',0,1,1],['devFree','無太監管制：隨時可以出城（1 開／0 關）',0,1,1]]]);
