function vbFree(id){var m=VB.M[id];if(!m)return;(m.own||[]).forEach(function(o){try{if(o instanceof WebGLVertexArrayObject)gl.deleteVertexArray(o);else gl.deleteBuffer(o);}catch(e){}});delete VB.M[id];}
function morphApply(id,W){var V=varOf(id);if(!V||!V.mt)return;if(!V._p16)V._p16=V.p16;var q=vbDec(V._p16,Int16Array),f=new Float32Array(q.length);for(var i=0;i<q.length;i++)f[i]=q[i]/16000;
  V.mt.forEach(function(m){var w=(W||{})[m.k]||0;if(!w)return;var ix=V78.mt[id+m.k]||(V78.mt[id+m.k]={i:vbDec(m.i,Uint16Array),d:vbDec(m.d,Int16Array)});for(var k=0;k<ix.i.length;k++){var v=ix.i[k]*3;f[v]+=ix.d[k*3]/16000*w;f[v+1]+=ix.d[k*3+1]/16000*w;f[v+2]+=ix.d[k*3+2]/16000*w;}});
  var u=new Uint8Array(f.buffer),s='',CH=0x8000;for(var c=0;c<u.length;c+=CH)s+=String.fromCharCode.apply(null,u.subarray(c,c+CH));V.p=btoa(s);delete V.p16;vbFree(id);}
