function hmHas(P){var pr=P.prop||{},jo=P.jo||{};return Object.keys(pr).some(function(k){return Math.abs(pr[k]-1)>1e-3;})||Object.keys(jo).some(function(k){var v=jo[k];return v&&(v[0]||v[1]||v[2]);});}
