function hmDrawSkel(){var cv=HMS.cv;if(!cv)return;var on=CE.on&&CE.studio&&HMS.skel,W=innerWidth,H=innerHeight;if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H;}var g=cv.getContext('2d');g.clearRect(0,0,W,H);cv.style.display=on?'block':'none';
  var a=hmActor(),VP=window.__VP;if(!on||!a||!a.P||!a.A.BI||!VP)return;var A=a.A,pt={};
  Object.keys(A.BI).forEach(function(n){var M=a.P.world[A.BI[n]+1];if(!M)return;var x=M[12],y=M[13],z=M[14],cw=VP[3]*x+VP[7]*y+VP[11]*z+VP[15];if(cw<=0.01)return;
    pt[n]=[((VP[0]*x+VP[4]*y+VP[8]*z+VP[12])/cw*0.5+0.5)*W,(1-((VP[1]*x+VP[5]*y+VP[9]*z+VP[13])/cw*0.5+0.5))*H];});
  g.lineWidth=2;g.strokeStyle='rgba(120,230,255,.85)';var R=humRaw();R.bones.forEach(function(b){if(b[1]==null)return;var p=pt[b[0]],q=pt[b[1]];if(!p||!q)return;g.beginPath();g.moveTo(q[0],q[1]);g.lineTo(p[0],p[1]);g.stroke();});
  var sel=CE.tab==='hc'?HMS.cb:HMS.bone;Object.keys(pt).forEach(function(n){var p=pt[n],s=n===sel;g.fillStyle=s?'#ff3a2a':'#fff';g.beginPath();g.arc(p[0],p[1],s?6:3.5,0,7);g.fill();if(s){g.strokeStyle='#fff';g.stroke();}});}
function hmPose(){var a=hmActor();if(!a)return;a.pos=[0,0,-0.5];a.yaw=0;a.speed=0;a.vc=0;a.once=null;if(a.y)a.y=0;a.hidden=false;[PL,EU,PR].forEach(function(o,i){if(o!==a){o.pos=[i===0?-3.4:i===1?-3.8:3.8,0,-0.8];o.speed=0;o.vc=0;o.hidden=true;}});window.__CT=[0,0,-0.5];
  var r=HMS.r=Math.max(1.4,Math.min(5,HMS.r||4.2)),th=cam.theta,ph=Math.max(0.35,Math.min(2.3,cam.phi)),h=a.h||1.8,s=Math.sin(ph),cz=s*Math.cos(th);
  if(cz<-0.01)r=Math.min(r,2.6/-cz);if(cz>0.01)r=Math.min(r,5.1/cz);var at=[0,h*(HMS.fy||0.5)-r*0.19,-0.5];
  window.__EYE=[at[0]+s*Math.sin(th)*r,at[1]+Math.cos(ph)*r,at[2]+cz*r];window.__AT=at;}
function hmView(k){if(k==='f'){cam.theta=0;cam.phi=1.52;}if(k==='s'){cam.theta=Math.PI/2;cam.phi=1.52;}if(k==='b'){cam.theta=Math.PI;cam.phi=1.52;}if(k==='t'){cam.phi=0.6;}if(k==='l')cam.theta+=Math.PI/4;if(k==='r')cam.theta-=Math.PI/4;
  if(k==='+')HMS.r=(HMS.r||4.4)*0.8;if(k==='-')HMS.r=(HMS.r||4.4)*1.25;if(k==='z'){HMS.r=1.6;}cam.hold=99;}
function hmOpen(){if(!HUM.A.pl||typeof charEditor!=='function')return;HMS.save={pl:PL.pos.slice(),eu:EU.pos.slice(),pr:PR.pos.slice(),py:PL.yaw,cam:[cam.theta,cam.phi,cam.r],hr:G.hr};try{closeCard();}catch(e){}
  charEditor();CE.studio=1;CE_ROLES.length=0;CE_ROLES.push(['pl','皇上'],['eu','太監'],['pr','太子']);CE.tab='hp';HMS.anim='idle';HMS.pause=0;HMS.r=4.2;cam.theta=0;cam.phi=1.52;ceRender();}
