  var _hp=humParams;humParams=function(r){var d=_hp(r),O=HUM_DEF_OVR[r];if(O){['prop','jo','corr'].forEach(function(k){if(O[k])d[k]=JSON.parse(JSON.stringify(O[k]));});}else{var s=hmLoad(r);if(s)['prop','jo','corr'].forEach(function(k){if(s[k])d[k]=JSON.parse(JSON.stringify(s[k]));});}return d;};
