// v84：動物改用野生動物套件（Quaternius Wild Animal Kit）為標準庫；黑猩猩、浣熊、奇幻小屋、遠方恐龍；
//      大灑幣、加考殿試、居民立場（支持／中立／不滿）、用詞與介面文字整理
var V84={coin:[],cd:0,ds:0,stance:null,sup:0,supD:-1,coinD:-1,coinM:0,err:{}};
function v84E(k,e){if(!V84.err[k]){V84.err[k]=1;console.error('v84 '+k,e&&e.message,e&&e.stack&&e.stack.slice(0,300));}}
function v84R(a){return a[Math.floor(Math.random()*a.length)];}
// ---------- 1) 動物：同一骨架的物種共用動作，依各物種骨段長度縮放位移 ----------
function v84AniPrep(id){if(typeof MK2==='undefined'||MK2.AG[id])return;var R=aniRec(id);if(!R)return;if(R.std!==2){v83AniPrep0(id);return;}
  var A=loadGLB(R.glb);if(R.base&&R.base!==id){v84AniPrep(R.base);var F=MK2.AG[R.base],tf=R.tf||[];A.anims={};
    Object.keys(F.anims).forEach(function(c){var an=F.anims[c];A.anims[c]={dur:an.dur,ch:an.ch.map(function(q){var k=tf[q.node];if(q.path!=='translation'||k==null||k===1)return q;var v=new Float32Array(q.v.length);for(var i=0;i<v.length;i++)v[i]=q.v[i]*k;return {node:q.node,path:q.path,t:q.t,v:v};})};});}
  MK2.AG[id]=A;}
var v83AniPrep0=null;
// 休息時的動作：吃草、低頭、換姿勢
function v84Rest(a){var L=['idle','idle','idle2','eat','low'].filter(function(c){return a.A.anims[c];});return L.length?v84R(L):'idle';}
// 野外動物（城門外原野）
function v84Wild(){if(typeof MK2==='undefined'||!MK2.ani||typeof ANIMALS==='undefined'||!aniRec('deer')||V84.wild)return;V84.wild=1;
  var L=[['deer',GATE_S+14,9],['deer',GATE_S+15.5,10.5],['stag',GATE_S+18,12],['donkey',GATE_S+3,-4.2],['bull',GATE_S+9,-11],['husky',MK_S0+4,-1.5]];
  L.forEach(function(q){var a=aniActor(q[0],roadPt(q[1],q[2]));if(a){a.roam=q[0]==='donkey'?0.6:q[0]==='husky'?4:3;a.street=1;MK2.ani.push(a);}});}
// ---------- 2) 靜態模型：浣熊、奇幻小屋、遠方恐龍；黑猩猩（市集雜耍的猴子） ----------
var V84S={L:[],ok:0};
// 找平坦、離路有距離的空地放模型
function v84Flat(p0,R,rad,road){var best=null,bs=1e9;for(var k=0;k<40;k++){var a=k*2.39996,r=k?R*Math.sqrt(k/40):0,p=[p0[0]+Math.cos(a)*r,p0[1]+Math.sin(a)*r];if(road&&typeof roadOff==='function'&&Math.abs(roadOff(p[0],p[1]))<road)continue;
    var lo=1e9,hi=-1e9;for(var j=0;j<8;j++){var y=gY(p[0]+Math.cos(j*0.785)*rad,p[1]+Math.sin(j*0.785)*rad);lo=Math.min(lo,y);hi=Math.max(hi,y);}var sc=hi-lo+r*0.01;if(sc<bs){bs=sc;best=p;best.lo=lo;}}return best||p0;}
function v84Static(){if(V84S.ok||typeof PROPS84==='undefined')return;V84S.ok=1;
  function add(k,pos,h,yaw,o){var g=PROPS84[k];if(!g)return null;var A=MK2.AG['p84_'+k]||(MK2.AG['p84_'+k]=loadGLB(g));var a=new GActor(A,{name:k,pos:[pos[0],0,pos[1]],yaw:yaw||0,h:h});a.st84=1;if(o)for(var q in o)a[q]=o[q];a.y=pos.lo!=null?pos.lo:gY(pos[0],pos[1]);a.update(0);V84S.L.push(a);return a;}
  add('raccoon',roadPt(MK_S0+12,2.9),0.5,-1.2,{far:40});
  var hp=v84Flat(roadPt(GATE_S+16,-11),9,3.2,7);add('house',hp,5.2,Math.atan2(-hp[0]+roadPt(GATE_S+16,0)[0],-hp[1]+roadPt(GATE_S+16,0)[1]),{far:120});
  // 恐龍：遠在山野，只做外型與比例
  [['trex',GATE_S+100,-50,5.5,2.2],['brachio',GATE_S+150,60,13,-2.2],['trike',GATE_S+92,46,3,-2.0],['stego',GATE_S+140,-58,4,2.4]].forEach(function(d){var p=v84Flat(roadPt(d[1],d[2]),10,d[3]*0.6,20);add(d[0],p,d[3],d[4],{far:400,dino:1});});
  if(PROPS84.chimp&&MK2.perf&&MK2.perf[0]){var c=add('chimp',[0,0],0.55,0,{far:40,chimp:1});if(c)V84S.chimp=c;}}
function v84StaticUpd(dt){if(!V84S.chimp)return;var c=V84S.chimp,p=MK2.perf[0];if(!p||!p.p)return;var y=(p.yaw||0)+0.9;c.pos[0]=p.p[0]+Math.sin(y)*0.75;c.pos[2]=p.p[1]+Math.cos(y)*0.75;c.yaw=(p.yaw||0);c.y=gY(c.pos[0],c.pos[2]);c.hidden=!!p.hide;if(c.A.anims.Idle&&c.clip!=='Idle')c.play('Idle',0.01);c.update(dt);}
function v84StaticDraw(u,depth){V84S.L.forEach(function(a){if(a.hidden||!a.P)return;if(Math.hypot(a.pos[0]-PL.pos[0],a.pos[2]-PL.pos[2])>a.far)return;if(depth&&a.dino)return;a.draw(u,depth);});}
// ---------- 3) 居民立場：支持者／中立／不滿者（依國事與民心每天重新分配） ----------
function v84Mood(){var I=(G.ind||[50,50,50,50]),m=(I[1]*0.5+I[0]*0.2+I[2]*0.15+I[3]*0.15)/100,u=typeof v83Unrest==='function'?v83Unrest():0.3;return Math.max(0,Math.min(1,m*0.85+(1-u)*0.15));}
function v84Stance(n){if(!n)return 'n';if(n.s84&&n.s84d===G.day)return n.s84;var m=v84Mood(),pS=0.1+0.55*m,pD=0.06+0.45*(1-m),r=Math.random();if(n.grp==='poor')pD+=0.08;if(n.grp==='adv'||n.grp==='tour'){pD*=0.4;}
  n.s84=r<pS?'s':r<pS+pD?'d':'n';n.s84d=G.day;return n.s84;}
function v84StanceCnt(){var c={s:0,n:0,d:0};(ST.npc||[]).forEach(function(n){if(!n.hide)c[v84Stance(n)]++;});return c;}
// 支持者遇到出巡的皇上：上前歡呼，民心微升（每天有上限）
function v84Cheer(dt){if(!ST.tour||UI.locked)return;if(V84.supD!==G.day){V84.supD=G.day;V84.sup=0;}V84.cheerT=(V84.cheerT||0)-dt;if(V84.cheerT>0)return;V84.cheerT=1.2;
  var P=[PL.pos[0],PL.pos[2]];(ST.npc||[]).forEach(function(n){if(n.hide||n.irr||n.down||n.p83||n.c84||v84Stance(n)!=='s'||n.ch84===G.day)return;var d=Math.hypot(n.p[0]-P[0],n.p[1]-P[1]);if(d>6.5)return;
    n.ch84=G.day;n.c84=2.4;if(typeof bubble==='function')bubble(n,v84R(['皇上萬歲！','吾皇聖明！','皇上辛苦了！','天佑大唐！','謝皇上恩典！']),1600);
    if(V84.sup<3&&Math.random()<0.5){V84.sup++;addInd([0,1,0,0]);}});
  (ST.npc||[]).forEach(function(n){if(n.c84>0)n.c84-=1.2;});}
// ---------- 4) 大灑幣 ----------
var V84_COIN_MAX=12;
