// ---------- 6) 鬼怪、居民、巡捕的異常 ----------
function v85Fix(dt){if(typeof ST==='undefined')return;
  // 鬼怪被制伏後一直跪在原地 → 時間到就押走
  (ST.mon||[]).forEach(function(m){if(m.hp!=null){m.fc85=(m.fc85||0)-dt;if(m.hp85!=null&&m.hp<m.hp85-0.5&&m.fc85<=0){m.fl85=0.12;m.fc85=0.6;}m.hp85=m.hp;}if(m.fl85>0){m.fl85-=dt;m.dim=m.fl85>0?2.6:1;}if(m.hide&&!m.hid85){m.hid85=1;if(m.p&&Math.hypot(m.p[0]-PL.pos[0],m.p[1]-PL.pos[2])<40)v85Dissolve([m.p[0],gY(m.p[0],m.p[1])+1,m.p[1]]);}else if(!m.hide)m.hid85=0;
    if(m.sub&&!m.hide){m.s85=(m.s85||0)+dt;if(m.s85>4.5){m.hide=true;m.sub=0;m.s85=0;m.flee=0;if(typeof toast==='function')toast('👮 巡捕制伏了一隻怪物，押回巡捕房。',2200);}}else m.s85=0;});
  // 被撞倒後有一段時間不會再倒；站著不動的時間（給姿勢用）
  (ST.npc||[]).forEach(function(n){if(n._d85&&!n.down)n.dImm=12;n._d85=!!n.down;if(n.dImm>0)n.dImm-=dt;n.still=(n.sp||0)<0.15&&!n.kb?(n.still||0)+dt:0;});
  // 巡捕體力：消耗減半、站著時慢慢恢復、累倒只休息一晚
  if(typeof copList==='function'){var L=copList(),hr=dt*19/(Math.max(1,CFG.dayMin||12)*60),P=V85.prevSt||[];
    L.forEach(function(c,i){var n=ST.cop[i],p=P[i];if(p!=null&&c.st<p)c.st=p-(p-c.st)*0.5;if(n&&!n.hide&&(n.sp||0)<0.2&&!n.monJob&&!n.job&&c.st>0)c.st=Math.min(100,c.st+hr*6);if(c.rest>G.day)c.rest=G.day;});
    V85.prevSt=L.map(function(c){return c.st;});}}
