function v115SparFly(){if(typeof V114==='undefined'||!V114.birds.length||typeof PADDY==='undefined')return;var P=PADDY,cx=(P.x0+P.x1)/2,cz=(P.z0+P.z1)/2,BF=V114.bf;V115.fd=null;BF.st='fly';BF.t=0;BF.dur=6+Math.random()*4;
  V114.birds.forEach(function(b){if(b.st==='fly')return;b.st='fly';b.hop=0;b.a=Math.atan2(b.p[0]-cx,b.p[2]-cz);b.rr=3.5+Math.random()*2.5;b.h=2.5+Math.random()*2;b.lift=0;});}
function v115Scare(){if(typeof PL==='undefined')return false;var x=PL.pos[0],z=PL.pos[2],nr=function(p,r){return Math.hypot(p[0]-x,p[2]-z)<r;};
  var g=V115.gulls.some(function(b){return b.st!=='fly'&&nr(b.p,3.5);}),sp=typeof V114!=='undefined'&&V114.birds.some(function(b){return b.st!=='fly'&&nr(b.p,b.st==='eat'||b.st==='go'?4:5);});
  var tr=typeof V114!=='undefined'&&V114.bf.st==='fly'&&V115.pbf==='ground'&&V114.birds.some(function(b){return nr(b.p,6.5);});if(typeof V114!=='undefined')V115.pbf=V114.bf.st;if(tr)return true;   // 麻雀剛被皇上驚飛
  if(!g&&!sp)return false;if(typeof V114!=='undefined'&&V114.birds.some(function(b){return b.st!=='fly';}))v115SparFly();return true;}
// 飼料粒
function v115Toss(n){var S=v115Spots(),gc=S.gc,f=[Math.sin(n.yaw),Math.cos(n.yaw)],h=[n.p[0]+f[0]*0.35,1.3,n.p[1]+f[1]*0.35];
  for(var i=0;i<9;i++){var a=Math.random()*Math.PI*2,r=Math.sqrt(Math.random())*1.0,tx=gc[0]+Math.sin(a)*r,tz=gc[1]+Math.cos(a)*r,T=0.55+Math.random()*0.2;
    V115.grain.push({p:h.slice(),v:[(tx-h[0])/T,(9.8*T*T/2-1.3)/T,(tz-h[2])/T],t:0,land:0,lt:0,rot:Math.random()*6});}
  if(typeof smp==='function')try{smp('coin',0.08);}catch(e){}}
function v115GrainUpd(dt){V115.grain.forEach(function(g){g.t+=dt;if(!g.land){g.v[1]-=9.8*dt;g.p[0]+=g.v[0]*dt;g.p[1]+=g.v[1]*dt;g.p[2]+=g.v[2]*dt;var y=(typeof gY==='function'?gY(g.p[0],g.p[2]):0)+0.008;if(g.p[1]<=y){g.p[1]=y;g.land=1;}}else g.lt+=dt;});
  V115.grain=V115.grain.filter(function(g){return !g.gone&&g.lt<60;});}
function v115GrainDraw(u,depth){if(!V115.grain.length||typeof bx!=='function')return;var C=V115.gcol||(V115.gcol=[0.86,0.72,0.42]);
  V115.grain.forEach(function(g){bx(u,depth,C,g.p,[0.035,0.016,0.025],g.rot);});}
// ---------- 海鷗（城門內空地） ----------
function v115GullInit(){var S=v115Spots();if(!S||typeof BIRD114==='undefined')return;for(var i=0;i<2;i++){var q=v115R(S.ga);V115.gulls.push({p:[q[0],0,q[1]],yaw:Math.random()*6.28,st:'idle',t:Math.random()*4,ph:0,tg:null});}}
function v115Gulls(dt){var S=v115Spots();if(!S)return;if(!V115.gulls.length)v115GullInit();var gy=function(x,z){return typeof gY==='function'?gY(x,z):0;},c=S.ga[Math.floor(S.ga.length/2)];
  var scare=v115Scare();
  V115.gulls.forEach(function(b,i){b.t-=dt;b.ph+=dt;var pd=Math.hypot(b.p[0]-PL.pos[0],b.p[2]-PL.pos[2]);
    if((b.st==='idle'||b.st==='walk')&&scare){b.st='fly';b.t=6+Math.random()*4;b.a=Math.atan2(b.p[0]-c[0],b.p[2]-c[1]);b.lift=0;b.rr=3.5+i*0.7;}
    if(b.st==='fly'){b.lift=Math.min(1,b.lift+dt*0.7);b.a+=dt*0.5;var x=c[0]+Math.sin(b.a)*b.rr,z=c[1]+Math.cos(b.a)*b.rr,y=gy(x,z)+0.6+3.2*b.lift+Math.sin(b.ph*0.8+i)*0.2;
      b.p[0]+=(x-b.p[0])*Math.min(1,dt*1.5);b.p[2]+=(z-b.p[2])*Math.min(1,dt*1.5);b.p[1]+=(y-b.p[1])*Math.min(1,dt*1.5);b.yaw=b.a+Math.PI/2;
      if(b.t<=0&&pd>5){var far=S.ga.filter(function(q){return Math.hypot(q[0]-PL.pos[0],q[1]-PL.pos[2])>5;});if(far.length){var q=v115R(far);b.st='land';b.tg=[q[0],gy(q[0],q[1]),q[1]];}else b.t=3;}return;}
    if(b.st==='land'){var T=b.tg,dx=T[0]-b.p[0],dz=T[2]-b.p[2],d=Math.hypot(dx,dz);if(d>0.02)b.yaw=Math.atan2(dx,dz);var v=Math.min(d,dt*3.2);b.p[0]+=dx/(d||1)*v;b.p[2]+=dz/(d||1)*v;b.p[1]+=(T[1]+Math.min(2,d*0.45)-b.p[1])*Math.min(1,dt*2.5);
      if(d<0.05&&Math.abs(b.p[1]-T[1])<0.06){b.st='idle';b.p=T.slice();b.t=2+Math.random()*4;}return;}
    b.p[1]=gy(b.p[0],b.p[2]);
    if(b.st==='walk'){var dx2=b.tg[0]-b.p[0],dz2=b.tg[1]-b.p[2],d2=Math.hypot(dx2,dz2);if(d2<0.08||b.t<=0){b.st='idle';b.t=2+Math.random()*5;return;}var ty2=Math.atan2(dx2,dz2);b.yaw+=Math.atan2(Math.sin(ty2-b.yaw),Math.cos(ty2-b.yaw))*Math.min(1,dt*5);b.p[0]+=Math.sin(b.yaw)*0.35*dt;b.p[2]+=Math.cos(b.yaw)*0.35*dt;return;}
    if(b.t<=0){if(Math.random()<0.6){var q2=v115R(S.ga);if(Math.hypot(q2[0]-b.p[0],q2[1]-b.p[2])<3.5){b.st='walk';b.tg=q2;b.t=12;return;}}b.t=2+Math.random()*4;b.yaw+=(Math.random()-0.5)*2;}});}
function v115GullAni(dt){if(typeof V114==='undefined')return;if(!V114.BA&&typeof BIRD114!=='undefined')V114.BA=loadGLB(BIRD114);if(!V114.BA)return;
  V115.gulls.forEach(function(b){if(!b.ga){b.ga=new GActor(V114.BA,{name:'海鷗',pos:[b.p[0],0,b.p[2]],h:V115.gh,idle:'Idle',walk:'Walk',run:'Walk'});b.ga.noTr103=1;}var a=b.ga;
    var c=b.st==='fly'?(Math.sin(b.ph*0.9)>0.2?'Glide':'Flap'):b.st==='land'?'Glide':b.st==='walk'?'Walk':'Idle';a.play(c,0.2);a.pos[0]=b.p[0];a.pos[2]=b.p[2];a.y=b.p[1];a.yaw=b.yaw+V114.fw;a.speed=0;a.update(b.st==='idle'&&v115Night()?dt*0.3:dt);});}
function v115GullDraw(u,depth){if(!V115.gulls.length)return;var c=V115.gulls[0].p;if(Math.hypot(PL.pos[0]-c[0],PL.pos[2]-c[2])>55)return;V115.gulls.forEach(function(b){if(b.ga&&b.ga.P)b.ga.draw(u,depth);});}
// ---------- C) 馬 ----------
function v115HorseStable(d){var tg=d.tg;if(d.st==='walk'&&!d.k115){var q=roadPt(GATE_S-5.4-Math.random()*3.2,3.9+Math.random()*1.8);d.tg=[q[0],q[1]];d.k115=1;}if(d.st!=='walk')d.k115=0;}
function v115HorseRun(d,dt){var S=v115Spots(),a=d.a;if(!S)return;d.t-=dt;var L=S.hl,pd=Math.hypot(a.pos[0]-PL.pos[0],a.pos[2]-PL.pos[2]);
  if(pd<2.6){a.speed=0;var ty=Math.atan2(PL.pos[0]-a.pos[0],PL.pos[2]-a.pos[2]);a.yaw+=Math.atan2(Math.sin(ty-a.yaw),Math.cos(ty-a.yaw))*Math.min(1,dt*2);v100Anim(d,v100Pick(a,['idle2','idle']),dt);return;}
  if(d.st==='gallop'){var T=L[d.k%L.length];if(Math.hypot(T[0]-a.pos[0],T[1]-a.pos[2])<1.2)d.k=(d.k+1)%L.length;v100Go(d,[T[0],T[1]],d.sp||4.2,dt);a.speed=Math.max(a.speed,2.6);v100Anim(d,null,dt);
    if(d.t<=0){d.st='trot';d.tg=v115R(S.hg);d.t=10;}return;}
  if(d.st==='trot'){if(v100Go(d,d.tg,1.3,dt)||d.t<=0){d.st='graze';d.t=7+Math.random()*9;}v100Anim(d,null,dt);return;}
  a.speed=0;var clip=d.st==='graze'?v100Pick(a,['eat','low']):v100Pick(a,['idle2','idle']);
  if(d.t<=0){var r=Math.random();if(r<0.55){d.st='gallop';d.t=12+Math.random()*10;var bk=0,bd=1e9;L.forEach(function(q,i){var dd=Math.hypot(q[0]-a.pos[0],q[1]-a.pos[2]);if(dd<bd){bd=dd;bk=i;}});d.k=bk;d.sp=3.8+Math.random()*1.2;
      var o=V100.horses.filter(function(h){return h!==d&&h.v115&&h.st==='gallop';})[0];if(o){d.k=(o.k+Math.floor(L.length/2))%L.length;d.sp=o.sp;}}   // 兩匹一起跑時錯開半圈
    else if(r<0.8){d.st='trot';d.tg=v115R(S.hg);d.t=10;}else{d.st=Math.random()<0.6?'graze':'rest';d.t=5+Math.random()*6;}}
  v100Anim(d,clip,dt);}
function v115Horses(){if(typeof V100==='undefined'||!V100.made||V115.hm)return;var S=v115Spots();if(!S||!V100.horses.length)return;V115.hm=1;
  if(V100.horses.length<3&&typeof aniActor==='function'){var a=aniActor('horse',S.hg[0].slice());if(a){a.id87='horse';V100.horses.push({a:a,st:'graze',t:4,tg:null});}}
  V100.horses.forEach(function(d,i){if(i===0){d.stable=1;return;}d.v115=1;var q=S.hg[(i*7)%S.hg.length];d.a.pos[0]=q[0];d.a.pos[2]=q[1];d.st=i===1?'gallop':'graze';d.t=i===1?14:6;d.k=0;d.sp=4.2;});}
// ---------- D) 皇上每日行蹤（不顯示） ----------
function v115Zone(){if(typeof SIT!=='undefined'&&SIT.on&&SIT.seat)return 'seat:'+(SIT.seat.name||'椅子');if(typeof V8B!=='undefined'&&V8B.bed)return 'bed';
  var x=PL.pos[0],z=PL.pos[2],d=function(p){return p?Math.hypot(p[0]-x,p[1]-z):1e9;};if(typeof inCap==='function'&&!inCap(x,z))return 'out';
  if(typeof PADDY!=='undefined'&&x>PADDY.x0-1&&x<PADDY.x1+1&&z>PADDY.z0-1&&z<PADDY.z1+1)return 'paddy';
  if(typeof V100!=='undefined'&&V100.stable&&d(V100.stable.p)<4.5)return 'stable';if(typeof RACK!=='undefined'&&d(RACK.pos)<4)return 'rack';
  if(typeof hero!=='undefined'&&hero&&hero.pos&&d([hero.pos[0],hero.pos[2]])<3)return 'rabbit';if(typeof roadS==='function'&&roadS(x,z)>GATE_S-4.5)return 'gate';return 'pal';}
function v115Day(){if(!G.a115||G.a115.d!==G.day){if(G.a115&&G.a115.d===G.day-1)G.y115=G.a115;G.a115={d:G.day,z:{},c:{}};}return G.a115;}
function v115Cnt(k){try{var A=v115Day();A.c[k]=(A.c[k]||0)+1;}catch(e){}}
function v115Track(){var T=G.day*24+(G.hr||0);if(V115.lt!=null){var dh=T-V115.lt;if(dh>0&&dh<0.5){var A=v115Day(),z=v115Zone();A.z[z]=(A.z[z]||0)+dh;}}V115.lt=T;}
function v115Sc(h){var n=Math.round(h/2);return n<=1?'一個多時辰':n===2?'兩個時辰':['','','','三','四','五','六','七','八','九','十','十一','十二'][Math.min(12,n)]+'個時辰';}
function v115YTopics(){var Y=G.y115&&G.y115.d===G.day-1?G.y115:null,L=[];if(!Y)return L;var Z=Y.z||{},C=Y.c||{},Y4=G.y114&&G.y114.d===G.day-1?G.y114:null;
  var seat=0,best=null;Object.keys(Z).forEach(function(k){if(k.indexOf('seat:')===0){seat+=Z[k];if(!best||Z[k]>Z[best])best=k;}});
  var court=Y4?Y4.court:0,busy=court||C.acad||C.ds||(Y4&&(Y4.acc||Y4.rej||Y4.ds));
  if(seat>=5&&!busy)L.push(['皇上昨天一整天就坐在椅子上，什麼正事也沒做。',[['跟罵','坐一整天，國事誰管？'],['護主','說不定是在想國家大事。'],['質疑','官爺天天站崗，怎麼知道宮裡的事？'],['附和','我家那口子也是這樣，坐下就不起來。']]]);
  else if(best&&Z[best]>=3)L.push(['聽說皇上昨天在'+best.slice(5)+'上一坐就是'+v115Sc(Z[best])+'，動都不動。',[['跟罵','坐著就能治天下？'],['護主','坐著也是在想事情嘛。'],['質疑','誰在旁邊數時辰的？']]]);
  if((Z.bed||0)>=10)L.push(['皇上昨天在龍床上睡了'+v115Sc(Z.bed)+'，太陽曬到屁股才起來。',[['跟罵','咱們天沒亮就下田了！'],['護主','皇上批奏章到半夜，多睡點也應該。'],['附和','能睡是福啊。']]]);
  if((Z.out||0)>=2)L.push(['皇上昨天在城外逛了'+v115Sc(Z.out)+'，巡捕跟得腿都快斷了。',[['附和','難怪那天街上巡捕特別多。'],['質疑','微服出巡，陣仗那麼大誰認不出來？'],['護主','皇上這是在看民間疾苦。']]]);
  else if(Z.out>0.3)L.push(['皇上昨天出城走了一圈，沒多久就回宮了。',[['質疑','這樣能看到什麼民情？'],['附和','來去匆匆的，我都沒瞧見。']]]);
  if((Z.paddy||0)>=0.5)L.push(['皇上昨天跑到稻田邊，看麻雀看了好久。',[['附和','皇上也關心農事呢。'],['跟罵','看麻雀？不如看看咱們的稅。']]]);
  if((Z.stable||0)>=0.5)L.push(['皇上昨天在御馬房待了半天，八成又想騎馬出城。',[['附和','皇上是馬上得天下的嘛。'],['害怕','可別又要打仗了……']]]);
  if((Z.rack||0)>=0.7)L.push(['皇上昨天在兵器架那兒練了'+v115Sc(Z.rack)+'的武。',[['附和','皇上身手可不是蓋的。'],['質疑','練武有用，國事誰批？']]]);
  if((Z.rabbit||0)>=0.5)L.push(['皇上昨天陪白兔娘娘玩了好久，宮女都看傻了。',[['附和','皇上心腸軟，連兔子都疼。'],['跟罵','陪兔子的時間比見百姓還多！']]]);
  if((Z.gate||0)>=1)L.push(['皇上昨天在城門口晃了好一陣子，害我站得筆直，一點都不敢偷懶。',[['附和','哈哈，官爺也有怕的時候。'],['質疑','您平常偷懶的事皇上不知道吧？']]]);
  if(C.coin)L.push(['皇上昨天在街上大灑幣，撒了'+(C.coin>10?'十幾':['','一','兩','三','四','五','六','七','八','九','十'][C.coin])+'回，百姓搶成一團。',[['附和','我也撿到一枚！'],['跟罵','錢是這樣撒的嗎？國庫都要空了。'],['護主','皇上這是體恤百姓。']]]);
  if(C.acad)L.push(['皇上昨天進書院讀書，聽說很用功。',[['附和','肯讀書的皇上，天下之福。'],['質疑','讀書讀到考試還答錯？']]]);
  else if(!busy)L.push(['皇上昨天一整天沒進書院，連書都沒翻一頁。',[['跟罵','自己不讀書，還要考別人？'],['護主','皇上國事忙，哪有空。']]]);
  (G.hist||[]).filter(function(h){return h.day===G.day-1&&(h.good||h.bad);}).slice(-2).forEach(function(h){
    if(h.bad&&!h.good)L.push(['皇上昨天在朝上議「'+v114Cut(h.title,14)+'」，選了「'+v114Cut(h.pick,14)+'」，我看是失策。',[['附和','我也覺得不妥。'],['質疑','官爺比宰相還懂治國？'],['護主','皇上自有考量。'],['跟罵','又是拍腦袋做的決定。']]]);
    else if(h.good)L.push(['皇上昨天在朝上議「'+v114Cut(h.title,14)+'」，選了「'+v114Cut(h.pick,14)+'」，處置得漂亮。',[['附和','這回皇上是真英明。'],['質疑','說不定只是運氣好。']]]);});
  return L;}
